document.addEventListener("DOMContentLoaded", () => {
  initApp();
});

function initApp() {
  loadSavedTheme();
  setupEventListeners();
  handleHashNavigation();
  updateRoleContext();
}

function loadSavedTheme() {
  const saved = localStorage.getItem("rugos_theme") || "light";
  setTheme(saved);
}

function setTheme(theme) {
  AppState.theme = theme;
  localStorage.setItem("rugos_theme", theme);
  document.body.classList.remove("theme-dark", "theme-light");
  document.body.classList.add(theme === "light" ? "theme-light" : "theme-dark");

  const themeIcon = document.getElementById("themeIcon");
  const themeLabel = document.getElementById("themeLabel");
  if (themeIcon && themeLabel) {
    if (theme === "dark") {
      themeIcon.textContent = "☀️";
      themeLabel.textContent = "Light Mode";
    } else {
      themeIcon.textContent = "🌙";
      themeLabel.textContent = "Dark Mode";
    }
  }
}

function toggleTheme() {
  setTheme(AppState.theme === "dark" ? "light" : "dark");
}

function setupEventListeners() {
  const themeBtn = document.getElementById("themeToggleBtn");
  if (themeBtn) themeBtn.addEventListener("click", toggleTheme);

  const sidebarToggle = document.getElementById("sidebarToggle");
  const sidebar = document.getElementById("appSidebar");
  if (sidebarToggle && sidebar) {
    sidebarToggle.addEventListener("click", () => sidebar.classList.toggle("collapsed"));
  }

  const navItems = document.querySelectorAll(".nav-item");
  navItems.forEach(item => {
    item.addEventListener("click", (e) => {
      e.preventDefault();
      navItems.forEach(i => i.classList.remove("active"));
      item.classList.add("active");
      const target = item.getAttribute("data-module");
      AppState.activeDetail = null;
      switchView(target);
    });
  });

  const roleSelector = document.getElementById("roleSelector");
  if (roleSelector) {
    roleSelector.addEventListener("change", (e) => {
      AppState.activeRole = e.target.value;
      updateRoleContext();
    });
  }

  const bpToggle = document.getElementById("blueprintToggle");
  const bpBanner = document.getElementById("blueprintBanner");
  if (bpToggle) {
    bpToggle.addEventListener("change", (e) => {
      AppState.blueprintMode = e.target.checked;
      document.body.classList.toggle("blueprint-active", AppState.blueprintMode);
      if (bpBanner) bpBanner.style.display = AppState.blueprintMode ? "flex" : "none";
      renderCurrentView();
    });
  }

  const bpDismiss = document.getElementById("bpDismiss");
  if (bpDismiss) {
    bpDismiss.addEventListener("click", () => {
      if (bpToggle) bpToggle.checked = false;
      AppState.blueprintMode = false;
      document.body.classList.remove("blueprint-active");
      if (bpBanner) bpBanner.style.display = "none";
      renderCurrentView();
    });
  }

  const notifBtn = document.getElementById("notifBtn");
  if (notifBtn) notifBtn.addEventListener("click", toggleAlertDrawer);

  const e2eBtn = document.getElementById("e2eSimBtn");
  if (e2eBtn) e2eBtn.addEventListener("click", openE2ESimulator);

  const searchInput = document.getElementById("globalSearchInput");
  if (searchInput) {
    searchInput.addEventListener("keyup", (e) => {
      if (e.key === "Enter") handleGlobalSearch(searchInput.value.trim().toLowerCase());
    });
  }

  window.addEventListener("hashchange", handleHashNavigation);
}

function handleGlobalSearch(query) {
  if (!query) return;
  const foundOrder = AppState.orders.find(o => o.orderId.toLowerCase().includes(query) || o.marketplaceOrderId.toLowerCase().includes(query));
  if (foundOrder) { openOrderDetail(foundOrder.orderId); return; }
  const foundSku = AppState.skus.find(s => s.sku.toLowerCase().includes(query) || s.title.toLowerCase().includes(query));
  if (foundSku) { openSkuStudioModal(foundSku.sku); return; }
  const foundAudit = AppState.courierAudit.find(a => a.awb.toLowerCase().includes(query));
  if (foundAudit) { openCourierAuditDetail(foundAudit.awb); return; }
  showToast(`No exact match found for "${query}". Found related records in catalog.`, "info");
}

function handleHashNavigation() {
  const hash = window.location.hash;
  if (hash) {
    const navMatch = document.querySelector(`.nav-item[href="${hash}"]`);
    if (navMatch) {
      document.querySelectorAll(".nav-item").forEach(i => i.classList.remove("active"));
      navMatch.classList.add("active");
      const mod = navMatch.getAttribute("data-module");
      AppState.activeModule = mod;
      AppState.activeDetail = null;
      renderCurrentView();
      return;
    }
  }
  AppState.activeModule = "mod8";
  AppState.activeDetail = null;
  const defNav = document.querySelector(`.nav-item[data-module="mod8"]`);
  if (defNav) {
    document.querySelectorAll(".nav-item").forEach(i => i.classList.remove("active"));
    defNav.classList.add("active");
  }
  renderCurrentView();
}

function switchView(moduleKey) {
  if (moduleKey === "mod2-history") moduleKey = "mod2-hist";
  AppState.activeModule = moduleKey;
  AppState.activeDetail = null;
  const navItem = document.querySelector(`.nav-item[data-module="${moduleKey}"]`);
  if (navItem) {
    document.querySelectorAll(".nav-item").forEach(i => i.classList.remove("active"));
    navItem.classList.add("active");
    const href = navItem.getAttribute("href");
    if (href && window.location.hash !== href) {
      try {
        history.pushState(null, "", href);
      } catch (err) {}
    }
  }
  renderCurrentView();
}

function updateRoleContext() {
  const tag = document.getElementById("userRoleTag");
  const roleNames = {
    admin: "Super Admin",
    india_wh: "India WH Mgr",
    usa_wh: "USA 3PL WH",
    logistics: "Logistics Lead",
    finance: "Finance Lead",
    auditor: "Statutory Auditor"
  };
  if (tag) tag.textContent = roleNames[AppState.activeRole] || AppState.activeRole || "Management";
  renderCurrentView();
}

function changeWarehouseFilter(facilityCode) {
  AppState.activeWarehouseFilter = facilityCode;
  const switcher = document.getElementById("warehouseSwitcher");
  if (switcher) switcher.value = facilityCode;
  const label = facilityCode === "india" ? "🇮🇳 India Origin (Bhadohi/ICD)" :
    facilityCode === "usa" ? "🇺🇸 USA 3PL (Edison/FBA)" : "Global (All Hubs)";
  showToast(`Active Warehouse Scope: ${label}`, "info");
  renderCurrentView();
}

function switchActiveRole(roleName) {
  AppState.activeRole = roleName;
  const switcher = document.getElementById("roleSwitcher");
  if (switcher) switcher.value = roleName;
  const tag = document.getElementById("userRoleTag");
  if (tag) tag.textContent = roleName;
  showToast(`Switched operational view to: ${roleName}`, "success");
  renderCurrentView();
}

// Toast Notifications
function showToast(message, type = "success") {
  const container = document.getElementById("toastContainer");
  if (!container) return;
  const toast = document.createElement("div");
  toast.className = `toast-msg ${type}`;
  toast.innerHTML = `
    <span>${type === 'success' ? '✓' : type === 'danger' ? '✕' : 'ℹ'}</span>
    <span>${message}</span>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translateY(10px)";
    setTimeout(() => toast.remove(), 250);
  }, 3200);
}

// ============================================================================
// 3. TABLE FILTERING, SORTING & PAGINATION UTILITIES
// ============================================================================

function setTableSearch(tableKey, value) {
  AppState.tableFilters[tableKey].search = value.toLowerCase();
  AppState.tableFilters[tableKey].page = 1;
  renderCurrentView();
}

function setTableFilter(tableKey, filterKey, value) {
  AppState.tableFilters[tableKey][filterKey] = value;
  AppState.tableFilters[tableKey].page = 1;
  renderCurrentView();
}

function setTableSort(tableKey, columnKey) {
  const f = AppState.tableFilters[tableKey];
  if (f.sortBy === columnKey) {
    f.sortOrder = f.sortOrder === "asc" ? "desc" : "asc";
  } else {
    f.sortBy = columnKey;
    f.sortOrder = "asc";
  }
  renderCurrentView();
}

function setTablePage(tableKey, pageNum) {
  AppState.tableFilters[tableKey].page = pageNum;
  renderCurrentView();
}

function setTablePageSize(tableKey, size) {
  AppState.tableFilters[tableKey].pageSize = parseInt(size);
  AppState.tableFilters[tableKey].page = 1;
  renderCurrentView();
}

function paginateArray(items, page, pageSize) {
  const total = items.length;
  const totalPages = Math.ceil(total / pageSize) || 1;
  const validPage = Math.min(Math.max(page, 1), totalPages);
  const start = (validPage - 1) * pageSize;
  const paginated = items.slice(start, start + pageSize);
  return { items: paginated, total, totalPages, currentPage: validPage, start: start + 1, end: Math.min(start + pageSize, total) };
}

