function updateUser(email) {
  const u = AppState.users.find(user => user.email === email);
  if (!u) return;

  const oldRole = u.role;
  const newRole = document.getElementById("editUserRole").value;
  u.name = document.getElementById("editUserName").value.trim() || u.name;
  u.role = newRole;
  u.status = document.getElementById("editUserStatus").value;

  const checkedBoxes = Array.from(document.querySelectorAll('input[name="editUserWhCheckbox"]:checked')).map(cb => cb.value);
  if (checkedBoxes.length === AppState.warehouses.length) {
    u.whAccess = "All Warehouses (Global)";
  } else if (checkedBoxes.length > 0) {
    u.whAccess = checkedBoxes.join(", ");
  } else {
    u.whAccess = "Unassigned";
  }

  // Update role counts if role changed
  if (oldRole !== newRole) {
    const oldR = AppState.roles.find(r => r.name === oldRole);
    if (oldR && oldR.userCount > 0) oldR.userCount--;
    const newR = AppState.roles.find(r => r.name === newRole);
    if (newR) newR.userCount = (newR.userCount || 0) + 1;
  }

  closeModal("crudModal");
  showToast(`Updated user ${u.name}: Role [${newRole}], Facilities [${u.whAccess}].`, "success");
  renderCurrentView();
}


function confirmDeleteUser(email) {
  const modal = document.getElementById("deleteConfirmModal");
  const msg = document.getElementById("deleteModalMessage");
  const btn = document.getElementById("confirmDeleteBtn");

  msg.textContent = `Are you sure you want to revoke access for ${email}?`;
  btn.onclick = () => {
    AppState.users = AppState.users.filter(u => u.email !== email);
    closeModal("deleteConfirmModal");
    showToast(`User access revoked for ${email}.`, "danger");
    renderCurrentView();
  };
  modal.style.display = "flex";
}

