function saveNewOrder() {
  const orderId = document.getElementById("formOrderId").value.trim();
  const channel = document.getElementById("formOrderChannel").value;
  const buyer = document.getElementById("formOrderBuyer").value.trim() || "Valued Client";
  const email = document.getElementById("formOrderEmail").value.trim() || "client@domain.com";
  const address = document.getElementById("formOrderAddress").value.trim() || "New York, NY, United States";
  const skuCode = document.getElementById("formOrderSku").value;
  const qty = parseInt(document.getElementById("formOrderQty").value) || 1;
  const wh = document.getElementById("formOrderWh").value;

  const sku = AppState.skus.find(s => s.sku === skuCode) || AppState.skus[0];
  const unitPrice = sku.sellingPriceUSD;
  const subtotal = unitPrice * qty;
  const tax = subtotal * 0.0825;
  const total = subtotal + tax;

  const channelNames = { amazon: "Amazon US", etsy: "Etsy Direct", walmart: "Walmart US", b2b: "B2B Wholesale Export" };

  const newOrder = {
    orderId,
    channel: channelNames[channel],
    channelIcon: channel,
    marketplaceOrderId: `API-${Date.now().toString().slice(-8)}`,
    orderDate: new Date().toISOString().replace('T', ' ').slice(0, 19) + " UTC",
    buyerName: buyer,
    buyerEmail: email,
    buyerPhone: "+1 (555) 019-2834",
    shippingAddress: address,
    billingAddress: "Same as Shipping Address",
    sku: skuCode,
    qty,
    unitPriceUSD: unitPrice,
    subtotalUSD: subtotal,
    shippingChargedUSD: 0.00,
    taxUSD: tax,
    totalOrderUSD: total,
    status: "Imported & Mapped",
    fulfillmentWh: wh,
    stockAllocation: `Allocated to ${wh.split(' ')[0]}`,
    allocationTimestamp: new Date().toISOString(),
    courier: "FedEx Standard Priority",
    awb: `7894-${Math.floor(1000 + Math.random() * 9000)}-${Math.floor(100 + Math.random() * 900)}`,
    labelGenerated: false,
    trackingStatus: "Manifest Generated — Ready for Pick",
    shippingCostEst: 42.00,
    shippingCostAct: 42.00,
    exportInvoice: `EXP-INV-2026-${Math.floor(200 + Math.random() * 800)}`,
    mtoNeeded: false,
    mappingException: false,
    history: [{ time: new Date().toISOString().slice(0, 19), action: "Order Created", detail: "Manual entry / API ingestion completed." }]
  };

  // Atomic concurrency stock reservation
  if (wh.includes("USA") || wh.includes("Edison")) {
    if (sku.stock.usaAvailable >= qty) {
      sku.stock.usaAvailable -= qty;
      sku.stock.usaReserved = (sku.stock.usaReserved || 0) + qty;
    } else {
      sku.stock.usaReserved = (sku.stock.usaReserved || 0) + qty;
    }
  } else {
    if (sku.stock.indiaAvailable >= qty) {
      sku.stock.indiaAvailable -= qty;
      sku.stock.indiaPacked = (sku.stock.indiaPacked || 0) + qty;
    } else {
      sku.stock.indiaPacked = (sku.stock.indiaPacked || 0) + qty;
    }
  }

  // Record an immutable transaction entry into the SKU Movement History Ledger
  AppState.skuHistory.unshift({
    timestamp: new Date().toISOString().replace('T', ' ').slice(0, 19),
    sku: sku.sku,
    type: "Order Concurrency Reservation",
    qty: -qty,
    source: wh,
    dest: `Order ${orderId} (${channelNames[channel]})`,
    user: "Admin / Management",
    ref: `ORD-ALLOC: ${orderId}`
  });

  AppState.orders.unshift(newOrder);
  closeModal("crudModal");
  showToast(`Order ${orderId} created and allocated successfully with concurrency lock!`, "success");
  renderCurrentView();
}

