function saveNewSku() {
  const sku = document.getElementById("formSkuCode")?.value.trim() || `SKU-RUG-GEN-${Date.now().toString().slice(-4)}`;
  const barcode = document.getElementById("formSkuBarcode")?.value.trim() || `890432190${Math.floor(1000 + Math.random() * 9000)}`;
  const title = document.getElementById("formSkuTitle")?.value.trim() || "Handcrafted Master Wool Rug";
  const collection = document.getElementById("formSkuCollection")?.value.trim() || "Royal Heritage";
  const material = document.getElementById("formSkuMaterial")?.value.trim() || "100% Wool Pile";
  const construction = document.getElementById("formSkuConstruction")?.value.trim() || "Hand-Tufted";
  const size = document.getElementById("formSkuSize")?.value.trim() || "8 ft x 10 ft";
  const shape = document.getElementById("formSkuShape")?.value || "Rectangular";
  const weightKg = parseFloat(document.getElementById("formSkuWeight")?.value) || 25.0;
  const sellingPriceUSD = parseFloat(document.getElementById("formSkuPrice")?.value) || 600.00;
  const mfgCostINR = parseInt(document.getElementById("formSkuCostINR")?.value) || 15000;
  const mfgCostUSD = parseFloat((mfgCostINR / 83.9).toFixed(2));
  const imageUrl = document.getElementById("formSkuImageUrl")?.value.trim() || "https://images.unsplash.com/photo-1579656381226-5fc0f0100c3b?w=600&q=80";

  const newSku = {
    sku,
    title,
    collection,
    design: "Artisan Motif",
    material,
    construction,
    size,
    shape,
    pileHeight: "12 mm",
    knotDensity: "High Density",
    gsm: 3600,
    weightKg,
    sellingPriceUSD,
    mfgCostINR,
    mfgCostUSD,
    packingCostUSD: 12.00,
    allocatedLandedFreightUSD: 25.00,
    stock: { indiaAvailable: 20, indiaPacked: 0, inTransit: 0, usaAvailable: 0, usaReserved: 0, fba: 0 },
    mappings: { amazon: `B09${sku.slice(-4)}`, etsy: `ETS-${sku.slice(-4)}`, walmart: `WMT-${sku.slice(-4)}`, b2b: `B2B-${sku.slice(-4)}` },
    barcode,
    imageUrl
  };

  AppState.skus.unshift(newSku);
  closeModal("crudModal");
  showToast(`Master SKU ${sku} added successfully to catalog!`, "success");
  renderCurrentView();
}

