// Generic Client-Side Tab Switcher for Enterprise ERP Detail Pages
function switchDetailTab(tabId, btnElement) {
  const container = (btnElement && btnElement.closest('.full-detail-page')) || document;
  const nav = btnElement && btnElement.closest('.detail-tabs-nav');
  if (nav) {
    nav.querySelectorAll('.detail-tab-btn').forEach(btn => btn.classList.remove('active'));
    btnElement.classList.add('active');
  }
  container.querySelectorAll('.detail-tab-pane').forEach(pane => {
    pane.classList.remove('active');
  });
  const target = document.getElementById(tabId);
  if (target) {
    target.classList.add('active');
  }
}

