function setForecastHorizon(days) {
  AppState.forecastHorizon = parseInt(days);
  renderCurrentView();
}

function exportForecastCSV() {
  const horizon = AppState.forecastHorizon || 60;
  let csv = "SKU,Rug Title,Collection,Available USA 3PL,Daily Velocity (Units/Day),Projected Demand Units,Days of Supply,Projected Run-Out Date,Stockout Risk,Suggested Replenishment Rolls\n";
  
  (AppState.skus || []).forEach(s => {
    const usaStock = s.stock.usaAvailable || 0;
    const velocity = (s.sku.includes('HT-0810') ? 1.8 : s.sku.includes('HK-0912') ? 1.1 : s.sku.includes('DHU') ? 1.4 : 0.8);
    const projDemand = Math.round(velocity * horizon);
    const daysSupply = velocity > 0 ? (usaStock / velocity).toFixed(1) : "99.0";
    const runOutDate = new Date(Date.now() + parseFloat(daysSupply) * 86400000).toLocaleDateString();
    const risk = parseFloat(daysSupply) < 15 ? "CRITICAL" : parseFloat(daysSupply) < 30 ? "WARNING" : "HEALTHY";
    const suggestedBatch = Math.max(0, projDemand - usaStock + 20);
    
    csv += `"${s.sku}","${s.title}","${s.collection}",${usaStock},${velocity},${projDemand},${daysSupply},"${runOutDate}","${risk}",${suggestedBatch}\n`;
  });
  
  triggerDownload(`RugOS_${horizon}Day_Demand_Forecast.csv`, csv, "text/csv");
  showToast(`Exported ${horizon}-Day Demand Forecast CSV successfully!`, "success");
}

function initiateOceanReplenishmentBatch() {
  showToast("📦 Opening Module 5 Loading Plans for 40ft Container replenishment...", "info");
  setTimeout(() => {
    switchView("mod5-ship");
    setTimeout(() => {
      openCreateLoadingPlanModal();
    }, 200);
  }, 300);
}

function dismissAlert(alertId) {
  const alert = (AppState.activeAlerts || []).find(a => a.id === alertId);
  if (alert) {
    alert.resolved = true;
    AppState.activeAlerts = AppState.activeAlerts.filter(a => a.id !== alertId);
    showToast(`Alert ${alertId} dismissed successfully.`, "info");
    const pill = document.getElementById("alertsCountPill");
    if (pill) pill.textContent = AppState.activeAlerts.length;
    renderCurrentView();
  }
}

function testFireRule(ruleId) {
  const rule = (AppState.automations || []).find(r => r.id === ruleId) || { name: ruleId, action: "Action triggered" };
  showToast(`⚡ Test Fire Executed: ${rule.name} -> ${rule.action}`, "success");
}

function toggleAutomationRule(ruleId, enabled) {
  const rule = (AppState.automations || []).find(r => r.id === ruleId);
  if (rule) {
    rule.enabled = enabled;
    showToast(`Automation rule ${ruleId} is now ${enabled ? 'ACTIVE' : 'PAUSED'}.`, enabled ? "success" : "warning");
    renderCurrentView();
  }
}

function syncIntegrationWorker(workerId) {
  const worker = (AppState.integrationWorkers || []).find(w => w.id === workerId);
  if (!worker) return;
  showToast(`🔄 Synchronizing ${worker.name}... Connecting to endpoint...`, "info");
  setTimeout(() => {
    worker.lastRun = "Just now";
    worker.errorCount = 0;
    showToast(`✓ ${worker.name} synchronized successfully with 0 payload errors!`, "success");
    renderCurrentView();
  }, 400);
}

function syncAllIntegrationWorkers() {
  showToast("⚡ Initiating full gateway sweep: Amazon SP-API, Etsy, FedEx, ICEGATE & HDFC Bank...", "info");
  setTimeout(() => {
    (AppState.integrationWorkers || []).forEach(w => {
      w.lastRun = "Just now";
      w.errorCount = 0;
    });
    showToast("✓ All 5 integration workers synchronized cleanly with 100% gateway SLA!", "success");
    renderCurrentView();
  }, 500);
}

function retryFailedJob(jobId) {
  const job = (AppState.failedJobs || []).find(j => j.jobId === jobId);
  if (!job) return;
  showToast(`🔁 Re-transmitting ${job.jobId} with idempotent key ${job.idempotentKey}...`, "info");
  setTimeout(() => {
    AppState.failedJobs = AppState.failedJobs.filter(j => j.jobId !== jobId);
    showToast(`✓ Job ${jobId} successfully processed! Zero duplicate records generated.`, "success");
    renderCurrentView();
  }, 450);
}

function triggerCronJob(jobName) {
  showToast(`⏰ Scheduled Daemon Triggered: ${jobName} executed manually.`, "success");
}


