function addPoLineItemRow() {
  const container = document.getElementById("poLineItemsContainer");
  if (!container) return;
  const newRow = document.createElement("div");
  newRow.className = "po-line-row";
  newRow.style.cssText = "display: grid; grid-template-columns: 2fr 1fr 1fr 1fr auto; gap: 8px; margin-bottom: 8px; align-items: center;";
  newRow.innerHTML = `
    <select class="form-control po-item-sku" onchange="autoFillPoItemRate(this)">
      ${AppState.skus.map(s => `<option value="${s.sku}" data-title="${s.title}" data-cost="${s.mfgCostINR || 15000}">${s.sku} — ${s.title.slice(0, 30)}</option>`).join('')}
    </select>
    <input type="number" class="form-control po-item-qty" placeholder="Qty" value="10" min="1" oninput="calcPoModalTotals()">
    <input type="number" class="form-control po-item-rate" placeholder="Rate" value="${AppState.skus[1] ? (AppState.skus[1].mfgCostINR || 25000) : 25000}" min="1" oninput="calcPoModalTotals()">
    <input type="text" class="form-control po-item-total" placeholder="Total" value="" readonly style="background: var(--bg-card); font-family: var(--font-mono); font-weight: 700;">
    <button type="button" class="btn btn-xs btn-danger" onclick="removePoLineItemRow(this)">✕</button>
  `;
  container.appendChild(newRow);
  calcPoModalTotals();
}

function removePoLineItemRow(btn) {
  const row = btn.closest(".po-line-row");
  if (row) row.remove();
  calcPoModalTotals();
}

function autoFillPoItemRate(selectEl) {
  const opt = selectEl.selectedOptions[0];
  const cost = opt.getAttribute("data-cost") || 15000;
  const row = selectEl.closest(".po-line-row");
  if (row) {
    const rateInput = row.querySelector(".po-item-rate");
    if (rateInput) rateInput.value = cost;
    calcPoModalTotals();
  }
}

function calcPoModalTotals() {
  const rows = document.querySelectorAll(".po-line-row");
  let grandTotal = 0;
  rows.forEach(row => {
    const qty = parseFloat(row.querySelector(".po-item-qty")?.value) || 0;
    const rate = parseFloat(row.querySelector(".po-item-rate")?.value) || 0;
    const total = qty * rate;
    const totalInput = row.querySelector(".po-item-total");
    if (totalInput) totalInput.value = total.toLocaleString();
    grandTotal += total;
  });
  const display = document.getElementById("poGrandTotalDisplay");
  const curr = document.getElementById("newPoCurrency")?.value || "INR";
  if (display) display.textContent = (curr === "INR" ? "₹" : "$") + grandTotal.toLocaleString();
}

function saveNewPurchaseOrder() {
  const poNumber = document.getElementById("newPoNum").value.trim() || `PO-2026-${Date.now().toString().slice(-4)}`;
  const vendor = document.getElementById("newPoVendor").value.trim() || "Bhadohi Master Loom";
  const vendorContact = document.getElementById("newPoContact").value.trim() || "";
  const destWhId = document.getElementById("newPoWh").value;
  const destWh = AppState.warehouses.find(w => w.id === destWhId) || AppState.warehouses[0];
  const orderDate = document.getElementById("newPoOrderDate").value;
  const expectedDate = document.getElementById("newPoExpDate").value;
  const currency = document.getElementById("newPoCurrency").value;
  const paymentTerms = document.getElementById("newPoTerms").value;
  const notes = document.getElementById("newPoNotes").value;

  const rows = document.querySelectorAll(".po-line-row");
  const items = [];
  let totalQty = 0;
  let totalAmount = 0;

  rows.forEach(row => {
    const skuSelect = row.querySelector(".po-item-sku");
    const sku = skuSelect?.value;
    const title = skuSelect?.selectedOptions[0]?.getAttribute("data-title") || sku;
    const qty = parseInt(row.querySelector(".po-item-qty")?.value) || 0;
    const unitRate = parseFloat(row.querySelector(".po-item-rate")?.value) || 0;
    const amount = qty * unitRate;

    if (sku && qty > 0) {
      items.push({
        sku,
        title,
        size: "Master Rug Size",
        qty,
        unitRate,
        totalAmount: amount,
        receivedQty: 0
      });
      totalQty += qty;
      totalAmount += amount;
    }
  });

  if (items.length === 0) {
    showToast("Please add at least one SKU with valid quantity!", "error");
    return;
  }

  const newPo = {
    poNumber,
    vendor,
    vendorContact,
    vendorAddress: "Registered Loom / Mill Facility",
    destWhId,
    destWhName: destWh.name,
    orderDate,
    expectedDate,
    currency,
    status: "Issued",
    paymentTerms,
    items,
    totalQty,
    receivedQty: 0,
    totalAmount,
    notes
  };

  AppState.purchaseOrders.unshift(newPo);

  // Update pill count
  const pill = document.getElementById("poCountPill");
  if (pill) pill.textContent = AppState.purchaseOrders.length;

  closeModal("crudModal");
  showToast(`Purchase Order ${poNumber} issued to ${vendor} for ${totalQty} carpet rolls!`, "success");
  renderCurrentView();
}

