function savePoInwardReceipt(poNumber) {
  const po = AppState.purchaseOrders.find(p => p.poNumber === poNumber);
  if (!po) return;

  const inputs = document.querySelectorAll(".po-inward-qty");
  let totalInwardedThisSession = 0;

  inputs.forEach(input => {
    const skuCode = input.getAttribute("data-sku");
    const qty = parseInt(input.value) || 0;
    if (qty > 0) {
      // 1. Update PO item
      const item = po.items.find(i => i.sku === skuCode);
      if (item) {
        item.receivedQty = (item.receivedQty || 0) + qty;
        totalInwardedThisSession += qty;
      }

      // 2. Add actual stock to the destination warehouse in AppState.skus
      const targetSku = AppState.skus.find(s => s.sku === skuCode);
      if (targetSku && targetSku.stock) {
        if (po.destWhId === "WH-USA-01") {
          targetSku.stock.usaAvailable = (targetSku.stock.usaAvailable || 0) + qty;
        } else {
          targetSku.stock.indiaAvailable = (targetSku.stock.indiaAvailable || 0) + qty;
        }
      }

      // 3. Log into AppState.skuHistory
      AppState.skuHistory.unshift({
        timestamp: new Date().toISOString().replace('T', ' ').slice(0, 19),
        sku: skuCode,
        type: "PO Inward Receipt",
        qty: qty,
        source: po.vendor,
        dest: po.destWhName,
        user: "Warehouse Inward Lead",
        ref: po.poNumber
      });
    }
  });

  // Re-calculate PO received total & status
  po.receivedQty = po.items.reduce((sum, i) => sum + (i.receivedQty || 0), 0);
  if (po.receivedQty >= po.totalQty) {
    po.status = "Completed";
  } else {
    po.status = "Partially Received";
  }

  closeModal("crudModal");
  showToast(`Successfully inwarded ${totalInwardedThisSession} rolls into ${po.destWhName}! Inventory updated.`, "success");
  renderCurrentView();
}

