function exportPurchaseOrdersCSV() {
  const headers = ["PO Number", "Vendor", "Receiving Warehouse", "Order Date", "Expected Date", "Currency", "Total Qty", "Received Qty", "Total Amount", "Status"];
  const rows = (AppState.purchaseOrders || []).map(p => [
    p.poNumber,
    `"${p.vendor}"`,
    `"${p.destWhName}"`,
    p.orderDate,
    p.expectedDate,
    p.currency,
    p.totalQty,
    p.receivedQty,
    p.totalAmount,
    p.status
  ]);
  const csvContent = [headers.join(","), ...rows.map(r => r.join(","))].join("\n");
  downloadCSV("Purchase_Orders_Ledger.csv", csvContent);
  showToast("Exported Purchase Orders CSV successfully!", "success");
}

