function exportProfitabilityCSV() {
  let csv = "Order ID,Channel,Buyer,SKU,Qty,Gross Revenue USD,FOB Mill Cost USD,Ocean Landed Freight USD,Courier Freight USD,Platform Fee USD,Packaging Cost USD,Audit Recovery USD,Net Profit USD,Net Margin Pct\n";
  (AppState.orders || []).forEach(o => {
    const r = o.totalOrderUSD || 500;
    const s = (AppState.skus || []).find(item => item.sku === o.sku) || {};
    const q = o.qty || 1;
    const mfg = s.mfgCostUSD ? (s.mfgCostUSD * q) : (r * 0.28);
    const ocean = s.allocatedLandedFreightUSD ? (s.allocatedLandedFreightUSD * q) : 25;
    const courier = o.shippingCostAct || o.shippingCostEst || 40;
    let feeRate = 0.15;
    if (o.channel.includes("Wayfair")) feeRate = 0.18;
    else if (o.channel.includes("Etsy")) feeRate = 0.065;
    else if (o.channel.includes("B2B")) feeRate = 0.0;
    const fee = r * feeRate;
    const pack = s.packingCostUSD ? (s.packingCostUSD * q) : 10;
    const aud = (AppState.courierAudit || []).find(a => a.orderRef === o.orderId);
    const recov = (aud && aud.status.includes("Approved")) ? aud.varianceUSD : 0;
    const net = r - mfg - ocean - courier - fee - pack + recov;
    const pct = ((net / r) * 100).toFixed(1);
    csv += `"${o.orderId}","${o.channel}","${o.buyerName || 'Client'}","${o.sku}",${q},${r.toFixed(2)},${mfg.toFixed(2)},${ocean.toFixed(2)},${courier.toFixed(2)},${fee.toFixed(2)},${pack.toFixed(2)},${recov.toFixed(2)},${net.toFixed(2)},"${pct}%"\n`;
  });
  triggerDownload("RugOS_TrueCost_Profitability_Ledger.csv", csv, "text/csv");
  showToast("Downloaded RugOS True Cost & Profitability Ledger CSV successfully!", "success");
}

