function exportFullSkuHistoryCSV() {
  let csv = "Timestamp,SKU,Movement Type,Quantity,Source,Destination,Initiated By,Reference\n";
  (AppState.skuHistory || []).forEach(h => {
    csv += `"${h.timestamp}","${h.sku}","${h.type}",${h.qty},"${h.source}","${h.dest}","${h.user}","${h.ref || ''}"\n`;
  });
  triggerDownload("Complete_SKU_History_Ledger.csv", csv, "text/csv");
}

function renderSkuHistoryView() {
  const f = AppState.tableFilters.skuHistory || (AppState.tableFilters.skuHistory = { search: "", sku: "all", type: "all", sortBy: "timestamp", sortOrder: "desc", page: 1, pageSize: 10 });
  const allMovementTypes = Array.from(new Set((AppState.skuHistory || []).map(i => i.changeType || i.type || "Movement")));

  let filtered = (AppState.skuHistory || []).filter(item => {
    const matchesSearch = !f.search || item.sku.toLowerCase().includes(f.search) || item.refNo.toLowerCase().includes(f.search);
    const matchesType = f.type === "all" || item.changeType.toLowerCase() === f.type.toLowerCase();
    return matchesSearch && matchesType;
  });

  const pagination = paginateArray(filtered, f.page, f.pageSize);

  return `
    <div class="page-header" style="margin-bottom: 16px;">
      <div class="page-title-wrap">
        <h1 style="margin: 0; font-size: 20px;">⏱️ Inventory Transaction History</h1>
      </div>
      <div class="page-actions" style="display: flex; gap: 8px;">
        <button class="btn btn-sm btn-secondary" onclick="exportSkuHistoryCSV()">📥 Export Log</button>
      </div>
    </div>

    <!-- History Audit Filter Tabs -->
    <div class="status-filter-pills">
      <button class="filter-pill-btn ${f.type === 'all' ? 'active' : ''}" onclick="setTableFilter('skuHistory', 'type', 'all')">All Audit Logs (${AppState.skuHistory ? AppState.skuHistory.length : 0})</button>
      <button class="filter-pill-btn ${f.type === 'GRN' ? 'active' : ''}" onclick="setTableFilter('skuHistory', 'type', 'GRN')">📥 Stock In (GRN)</button>
      <button class="filter-pill-btn ${f.type === 'Dispatch' ? 'active' : ''}" onclick="setTableFilter('skuHistory', 'type', 'Dispatch')">📤 Sales Dispatch</button>
      <button class="filter-pill-btn ${f.type === 'Transfer' ? 'active' : ''}" onclick="setTableFilter('skuHistory', 'type', 'Transfer')">⇆ Warehouse Transfer</button>
    </div>

    <div class="table-toolbar-box">
      <div class="table-toolbar-left" style="flex-wrap: wrap; gap: 10px;">
        <!-- Search Input -->
        <div class="table-search-input-wrap" style="min-width: 320px;">
          <span class="table-search-icon">🔍</span>
          <input type="text" id="skuHistorySearchInput" placeholder="Search SKU, reference, user, or location..." value="${f.search}" oninput="setTableSearch('skuHistory', this.value)">
        </div>

        <!-- Comprehensive Movement Type Filter Dropdown -->
        <select class="table-filter-select" onchange="setTableFilter('skuHistory', 'type', this.value)" style="font-weight: 600; color: var(--brand-cyan); max-width: 280px;">
          <option value="all" ${f.type === 'all' ? 'selected' : ''}>🏷️ Filter by Movement Type (All)</option>
          ${allMovementTypes.map(t => `<option value="${t}" ${f.type === t ? 'selected' : ''}>${t}</option>`).join('')}
        </select>

        ${(f.search || f.sku !== 'all' || f.type !== 'all') ? `
          <button class="btn btn-xs btn-secondary" onclick="AppState.tableFilters.skuHistory = { search: '', sku: 'all', type: 'all', sortBy: 'timestamp', sortOrder: 'desc', page: 1, pageSize: 10 }; renderCurrentView();">
            ✕ Clear Filters
          </button>
        ` : ''}
      </div>

      <div class="table-toolbar-right" style="display: flex; align-items: center; gap: 10px;">
        <span style="font-size: 11px; color: var(--text-dim);">${filtered.length} matching transaction records</span>
      </div>
    </div>

    <!-- SKU History Ledger Table -->
    <div class="card">
      <div class="table-responsive">
        <table class="data-table">
          <thead>
            <tr>
              <th class="sortable" onclick="setTableSort('skuHistory', 'timestamp')">
                Timestamp ${f.sortBy === 'timestamp' ? `<span class="sort-icon">${f.sortOrder === 'asc' ? '▲' : '▼'}</span>` : ''}
              </th>
              <th class="sortable" onclick="setTableSort('skuHistory', 'sku')">
                Carpet Rug SKU ${f.sortBy === 'sku' ? `<span class="sort-icon">${f.sortOrder === 'asc' ? '▲' : '▼'}</span>` : ''}
              </th>
              <th class="sortable" onclick="setTableSort('skuHistory', 'type')">
                Movement Type & Action ${f.sortBy === 'type' ? `<span class="sort-icon">${f.sortOrder === 'asc' ? '▲' : '▼'}</span>` : ''}
              </th>
              <th class="sortable" onclick="setTableSort('skuHistory', 'qty')" style="text-align: center;">
                Quantity ${f.sortBy === 'qty' ? `<span class="sort-icon">${f.sortOrder === 'asc' ? '▲' : '▼'}</span>` : ''}
              </th>
              <th>Source Location</th>
              <th>Destination Hub</th>
              <th>Audit Ref</th>
              <th style="text-align: center;">📸 Packing Camera Snapshot</th>
              <th>Initiated By</th>
              <th style="text-align: center;">Actions</th>
            </tr>
          </thead>
          <tbody>
            ${pagination.items.length === 0 ? `
              <tr><td colspan="10" style="text-align: center; padding: 36px; color: var(--text-dim);">No transactions found matching "${f.search || f.sku || f.type}".</td></tr>
            ` : pagination.items.map(h => {
              const actualIndex = AppState.skuHistory.indexOf(h);
              const isPositive = (h.qty > 0) || (h.type && (h.type.includes('Inward') || h.type.includes('Receipt') || h.type.includes('Finish') || h.type.includes('Restock')));
              const isPackingProof = h.type && h.type.includes('Proof of Packing');
              const isOrder = h.ref && h.ref.startsWith('ORD-');
              const isTransfer = h.ref && (h.ref.startsWith('TRF-') || h.ref.startsWith('REP-'));
              const isReturn = h.ref && h.ref.startsWith('RMA-');
              const skuObj = AppState.skus.find(s => s.sku === h.sku);
              const rugImg = (skuObj && skuObj.imageUrl) || 'https://images.unsplash.com/photo-1600121848594-d8644e57abab?w=600&q=80';

              return `
                <tr>
                  <td>
                    <span style="font-family: var(--font-mono); font-size: 11px; color: var(--text-muted);">${h.timestamp}</span>
                  </td>
                  <td>
                    <div style="display: flex; align-items: center; gap: 8px;">
                      <img src="${rugImg}" style="width: 32px; height: 32px; border-radius: 4px; object-fit: cover; border: 1px solid var(--border-main);">
                      <div>
                        <a href="javascript:void(0)" onclick="openSkuDetail('${h.sku}')" style="font-family: var(--font-mono); color: var(--brand-cyan); font-weight: 700; text-decoration: none; font-size: 13px;">
                          ${h.sku}
                        </a>
                        <div style="font-size: 10px; color: var(--text-dim); max-width: 170px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${skuObj ? skuObj.title : ''}</div>
                      </div>
                    </div>
                  </td>
                  <td>
                    <!-- Interactive Movement Type Selector (Inline Reclassification) -->
                    <div style="display: flex; align-items: center; gap: 6px;">
                      <select class="table-status-select" onchange="changeSkuHistoryMovementType(${actualIndex}, this.value)" style="font-size: 11px; padding: 4px 24px 4px 10px; font-weight: 600;" title="Change Movement Type directly inline">
                        ${allMovementTypes.map(typeOpt => `
                          <option value="${typeOpt}" ${h.type === typeOpt ? 'selected' : ''}>${typeOpt}</option>
                        `).join('')}
                      </select>
                      <button class="btn btn-xs btn-secondary" onclick="openChangeMovementTypeModal(${actualIndex})" title="Open full Movement Type Change modal with audit notes" style="padding: 3px 6px; font-size: 10px;">✏️</button>
                    </div>
                    ${h.notes ? `<div style="font-size: 10px; color: var(--text-dim); margin-top: 3px; max-width: 220px;">${h.notes}</div>` : ''}
                  </td>
                  <td style="text-align: center;">
                    <strong style="font-family: var(--font-mono); font-size: 13px; color: ${isPositive ? 'var(--success)' : 'var(--warning)'};">
                      ${h.qty > 0 ? '+' + h.qty : h.qty} rolls
                    </strong>
                  </td>
                  <td><span style="font-size: 12px; color: var(--text-main);">${h.source}</span></td>
                  <td><span style="font-size: 12px; font-weight: 600; color: var(--text-main);">${h.dest}</span></td>
                  <td>
                    <div style="display: flex; align-items: center; gap: 6px;">
                      <code style="font-size: 11px; padding: 2px 6px; background: var(--bg-surface); border: 1px solid var(--border-main); border-radius: 3px; color: var(--brand-cyan); font-weight: 700;">
                        ${h.ref || 'SYS-LOG'}
                      </code>
                    </div>
                  </td>
                  <td style="text-align: center;">
                    <!-- Dedicated Packing Camera Snapshot Preview & Trigger -->
                    ${isPackingProof ? `
                      <div style="display: inline-flex; align-items: center; gap: 6px; cursor: pointer;" onclick="openPackingCameraSnapshotModal('${h.ref}', '${h.sku}')" title="Click to inspect 1080p camera snapshot & scale calibration">
                        <div style="position: relative; width: 34px; height: 34px; border-radius: 4px; overflow: hidden; border: 1.5px solid var(--brand-cyan); box-shadow: 0 2px 6px rgba(0,0,0,0.2);">
                          <img src="${rugImg}" style="width: 100%; height: 100%; object-fit: cover;">
                          <span style="position: absolute; bottom: 0; right: 0; background: rgba(0,0,0,0.85); color: var(--brand-cyan); font-size: 8px; padding: 1px 2px;">📷</span>
                        </div>
                        <div style="text-align: left;">
                          <span class="badge badge-success" style="font-size: 9px; padding: 2px 5px;">✓ 28.5 kg Sealed</span>
                          <div style="font-size: 9px; color: var(--brand-cyan); font-weight: 600;">Cam #01 Verified</div>
                        </div>
                      </div>
                    ` : `
                      <button class="btn btn-xs btn-secondary" onclick="openPackingCameraSnapshotModal('${h.ref}', '${h.sku}')" style="display: inline-flex; align-items: center; gap: 3px; font-size: 10px; padding: 3px 8px;">
                        📷 Snap Photo
                      </button>
                    `}
                  </td>
                  <td>
                    <span style="font-size: 11px; color: var(--text-muted); font-weight: 500;">${h.user}</span>
                  </td>
                  <td style="text-align: center;">
                    <div style="display: flex; gap: 4px; justify-content: center; flex-wrap: wrap;">
                      <button class="btn btn-xs btn-primary" onclick="openPackingCameraSnapshotModal('${h.ref}', '${h.sku}')" style="display: inline-flex; align-items: center; gap: 3px; font-weight: 700; background: linear-gradient(135deg, var(--brand-cyan), var(--brand-purple)); border: none; color: #fff;" title="Open Packing Camera Snapshot Studio">
                        📸 Snapshot
                      </button>
                      <button class="btn btn-xs btn-secondary" onclick="openChangeMovementTypeModal(${actualIndex})" title="Change Movement Type & Add Audit Reason">
                        🏷️ Type
                      </button>
                      ${isOrder ? `
                        <button class="btn btn-xs btn-secondary" onclick="openOrderDetail('${h.ref}')" title="Inspect Order">🛍️ Order</button>
                      ` : ''}
                      ${isTransfer ? `
                        <button class="btn btn-xs btn-secondary" onclick="openReplenishmentDetail('${h.ref}')" title="Inspect Transfer">⇆ Transfer</button>
                      ` : ''}
                      ${isReturn ? `
                        <button class="btn btn-xs btn-secondary" onclick="openReturnDetail('${h.ref}')" title="Inspect Return">🔄 Return</button>
                      ` : ''}
                      <button class="btn btn-xs btn-secondary" onclick="openSkuDetail('${h.sku}')" title="View Full SKU Profile">👁️ Sku</button>
                    </div>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>

      <!-- Pagination Footer -->
      <div class="table-pagination-footer">
        <div class="pagination-info">
          Showing <strong>${pagination.items.length ? pagination.start : 0}</strong> to <strong>${pagination.end}</strong> of <strong>${pagination.total}</strong> transaction entries
        </div>
        <div class="pagination-controls">
          <select class="rows-per-page-select" onchange="setTablePageSize('skuHistory', this.value)">
            <option value="5" ${f.pageSize === 5 ? 'selected' : ''}>5 per page</option>
            <option value="10" ${f.pageSize === 10 ? 'selected' : ''}>10 per page</option>
            <option value="25" ${f.pageSize === 25 ? 'selected' : ''}>25 per page</option>
            <option value="50" ${f.pageSize === 50 ? 'selected' : ''}>50 per page</option>
          </select>
          <button class="page-btn" ${pagination.currentPage === 1 ? 'disabled' : ''} onclick="setTablePage('skuHistory', ${pagination.currentPage - 1})">◀</button>
          ${Array.from({ length: pagination.totalPages }, (_, i) => i + 1).map(p => `
            <button class="page-btn ${p === pagination.currentPage ? 'active' : ''}" onclick="setTablePage('skuHistory', ${p})">${p}</button>
          `).join('')}
          <button class="page-btn" ${pagination.currentPage === pagination.totalPages ? 'disabled' : ''} onclick="setTablePage('skuHistory', ${pagination.currentPage + 1})">▶</button>
        </div>
      </div>
    </div>
  `;
}
window.renderSkuHistoryView = renderSkuHistoryView;

// Inline Movement Type Updater for SKU History
function changeSkuHistoryMovementType(index, newType) {
  if (AppState.skuHistory && AppState.skuHistory[index]) {
    const oldType = AppState.skuHistory[index].type;
    AppState.skuHistory[index].type = newType;
    showToast(`Movement Type updated from "${oldType}" to "${newType}" for SKU ${AppState.skuHistory[index].sku}`, 'success');
    renderCurrentView();
  }
}

// Full Modal to Change Movement Type with Audit Justification
function openChangeMovementTypeModal(targetIndex) {
  const modal = document.getElementById("crudModal");
  const modalBox = modal.querySelector(".modal-box");
  if (modalBox) {
    modalBox.classList.remove("modal-xl");
    modalBox.classList.add("modal-lg");
    modalBox.style.maxWidth = "620px";
  }

  const allMovementTypes = [
    "Inward Stock Creation",
    "Proof of Packing Sealed",
    "Order Allocation & Lock",
    "Inter-Warehouse Transfer",
    "Ocean Replenishment Inbound",
    "Courier Outbound Dispatch",
    "Physical Cycle Count Adjustment",
    "Customer Return Restock (RMA)",
    "Damaged / QC Scrap Write-Off",
    "MTO Production Finish"
  ];

  const hasIndex = (typeof targetIndex === "number" && AppState.skuHistory[targetIndex]);
  const item = hasIndex ? AppState.skuHistory[targetIndex] : (AppState.skuHistory[0] || {});
  const actualIndex = hasIndex ? targetIndex : 0;
  const skuObj = AppState.skus.find(s => s.sku === item.sku);

  const title = document.getElementById("crudModalTitle");
  const badge = document.getElementById("crudBadge");
  const body = document.getElementById("crudModalBody");
  const footer = document.getElementById("crudModalFooter");

  badge.textContent = "Audit Reclassification";
  badge.className = "badge badge-primary";
  title.innerHTML = `🏷️ Change Movement Type &bull; <code style="color: var(--brand-cyan); font-weight: 700;">${item.ref || 'SYS-LOG'}</code>`;

  body.innerHTML = `
    <div style="display: flex; flex-direction: column; gap: 16px;">
      ${!hasIndex ? `
        <div class="form-group">
          <label class="form-label" style="font-weight: 700;">Select Transaction Record to Reclassify:</label>
          <select id="modalSelectLedgerItem" class="form-control" onchange="openChangeMovementTypeModal(parseInt(this.value, 10))">
            ${(AppState.skuHistory || []).map((h, i) => `
              <option value="${i}" ${i === actualIndex ? 'selected' : ''}>
                [${h.timestamp}] ${h.sku} &bull; Current: ${h.type} (${h.ref})
              </option>
            `).join('')}
          </select>
        </div>
      ` : ''}

      <!-- Item Profile Card -->
      <div style="background: var(--bg-elevated); padding: 14px; border-radius: var(--radius-md); border: 1px solid var(--border-main); display: flex; gap: 12px; align-items: center;">
        <img src="${(skuObj && skuObj.imageUrl) || 'https://images.unsplash.com/photo-1600121848594-d8644e57abab?w=600&q=80'}" style="width: 48px; height: 48px; border-radius: 6px; object-fit: cover; border: 1px solid var(--border-main);">
        <div style="flex: 1;">
          <div style="display: flex; justify-content: space-between; align-items: flex-start;">
            <div>
              <strong style="font-size: 14px; color: var(--text-main); font-family: var(--font-mono);">${item.sku}</strong>
              <div style="font-size: 12px; color: var(--text-dim);">${skuObj ? skuObj.title : 'Odette Luxury Rug'}</div>
            </div>
            <span class="badge badge-secondary" style="font-size: 11px;">Current: ${item.type}</span>
          </div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 4px; display: flex; gap: 12px;">
            <span>Ref: <code style="color: var(--brand-cyan);">${item.ref}</code></span>
            <span>Recorded: <strong>${item.timestamp}</strong></span>
            <span>By: <strong>${item.user}</strong></span>
          </div>
        </div>
      </div>

      <!-- Movement Type Selector -->
      <div class="form-group">
        <label class="form-label" style="font-weight: 700; color: var(--brand-cyan); display: flex; justify-content: space-between;">
          <span>Select New SOW Movement Type:</span>
          <span style="font-size: 11px; color: var(--text-dim);">10 Standard SOW Movement Types</span>
        </label>
        <select id="modalNewMovementTypeSelect" class="form-control" style="font-size: 13px; font-weight: 600; padding: 8px 12px;">
          ${allMovementTypes.map(typeOpt => `
            <option value="${typeOpt}" ${item.type === typeOpt ? 'selected' : ''}>
              ${typeOpt.includes('Inward') ? '📥 ' :
                typeOpt.includes('Packing') ? '📸 ' :
                typeOpt.includes('Order') ? '🔒 ' :
                typeOpt.includes('Transfer') ? '⇆ ' :
                typeOpt.includes('Ocean') ? '🚢 ' :
                typeOpt.includes('Courier') ? '🚚 ' :
                typeOpt.includes('Cycle') ? '⚖️ ' :
                typeOpt.includes('Return') ? '🔄 ' :
                typeOpt.includes('Damaged') ? '⚠️ ' : '🪡 '}${typeOpt}
            </option>
          `).join('')}
        </select>
      </div>

      <!-- Movement Details Grid -->
      <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px;">
        <div class="form-group">
          <label class="form-label" style="font-size: 11px;">Quantity (Rolls):</label>
          <input type="number" id="modalMovementQtyInput" class="form-control" value="${item.qty || 1}">
        </div>
        <div class="form-group">
          <label class="form-label" style="font-size: 11px;">Source Location:</label>
          <input type="text" id="modalMovementSourceInput" class="form-control" value="${item.source || 'India Central WH'}">
        </div>
        <div class="form-group">
          <label class="form-label" style="font-size: 11px;">Destination Hub:</label>
          <input type="text" id="modalMovementDestInput" class="form-control" value="${item.dest || 'Packed & Staged'}">
        </div>
      </div>

      <!-- Mandatory Audit Trail Reason -->
      <div class="form-group">
        <label class="form-label" style="font-weight: 700; color: var(--warning);">
          📝 Reason for Movement Type Reclassification (Mandatory Audit Trail):
        </label>
        <textarea id="modalMovementReasonText" class="form-control" rows="2" placeholder="e.g., Physical QC re-inspection confirmed MTO loom finish batch, corrected classification from inward...">${item.notes || ''}</textarea>
      </div>
    </div>
  `;

  footer.innerHTML = `
    <button class="btn btn-secondary" onclick="closeModal('crudModal')">Cancel</button>
    <button class="btn btn-primary" onclick="saveSkuMovementTypeChange(${actualIndex})">
      ✓ Save Movement Type Change
    </button>
  `;

  modal.style.display = "flex";
}

// Save Movement Type Change from Modal
function saveSkuMovementTypeChange(index) {
  if (!AppState.skuHistory || !AppState.skuHistory[index]) {
    showToast("Invalid transaction record selected.", "error");
    return;
  }

  const newType = document.getElementById("modalNewMovementTypeSelect").value;
  const newQty = parseInt(document.getElementById("modalMovementQtyInput").value, 10) || 1;
  const newSource = document.getElementById("modalMovementSourceInput").value.trim();
  const newDest = document.getElementById("modalMovementDestInput").value.trim();
  const newReason = document.getElementById("modalMovementReasonText").value.trim();

  const oldType = AppState.skuHistory[index].type;
  AppState.skuHistory[index].type = newType;
  AppState.skuHistory[index].qty = newQty;
  if (newSource) AppState.skuHistory[index].source = newSource;
  if (newDest) AppState.skuHistory[index].dest = newDest;
  AppState.skuHistory[index].notes = newReason || `Reclassified from "${oldType}" to "${newType}" by QC Lead`;

  closeModal("crudModal");
  showToast(`Movement Type updated to "${newType}" for SKU ${AppState.skuHistory[index].sku} (Audit Logged)`, "success");
  renderCurrentView();
}

