  const dailyVelocity = sku.sku.includes('HT-0810') ? 1.8 : sku.sku.includes('HK-0912') ? 1.1 : sku.sku.includes('DHU') ? 1.4 : 0.8;
  
  const weeklySold = Math.round(dailyVelocity * 7);
