// --- BUYER & CUSTOMER MASTER ---
function renderBuyersMasterView() {
  const f = AppState.tableFilters.buyers || { search: "", tier: "all", sortBy: "name", sortOrder: "asc", page: 1, pageSize: 5 };
  let filtered = AppState.buyers.filter(b => {
    const matchesSearch = !f.search || b.name.toLowerCase().includes(f.search) || b.code.toLowerCase().includes(f.search) || b.country.toLowerCase().includes(f.search);
    const matchesTier = f.tier === "all" || b.tier.toLowerCase().includes(f.tier.toLowerCase());
    return matchesSearch && matchesTier;
  });

  filtered.sort((a, b) => {
    let valA = a[f.sortBy] ?? "";
    let valB = b[f.sortBy] ?? "";
    if (typeof valA === "string") valA = valA.toLowerCase();
    if (typeof valB === "string") valB = valB.toLowerCase();
    if (valA < valB) return f.sortOrder === "asc" ? -1 : 1;
    if (valA > valB) return f.sortOrder === "asc" ? 1 : -1;
    return 0;
  });

  const totalCreditUSD = AppState.buyers.reduce((sum, b) => sum + (b.creditLimitUSD || 0), 0);
  const totalOutstandingUSD = AppState.buyers.reduce((sum, b) => sum + (b.outstandingUSD || 0), 0);
  const pagination = paginateArray(filtered, f.page || 1, f.pageSize || 5);

  return `
    <div class="page-header">
      <div class="page-title-wrap">
        <h1>🏬 Buyer & Customer Master (Global B2B Accounts)</h1>
        <p>Master registry of international wholesale importers, retail chains, and authorized dealer bank branch accounts.</p>
      </div>
      <div class="page-actions">
        <button class="btn btn-secondary" onclick="exportBuyersCSV()">📥 Export Buyers CSV</button>
        <button class="btn btn-primary" onclick="openAddBuyerModal()">+ Add New Buyer</button>
      </div>
    </div>

    ${renderBlueprintSpec("Module 2 — International Buyer Master Governance (40 hrs)", "Configures B2B export buyer accounts with approved credit limits, authorized payment terms (LC at sight, Net-60, CAD), and linked AD code bank branches.")}

    <!-- Bento KPI Metrics -->
    <div class="bento-metrics-grid" style="grid-template-columns: repeat(4, 1fr); margin-bottom: 20px;">
      <div class="metric-card">
        <div class="metric-header"><span class="metric-label">Active B2B Buyer Accounts</span><span>🏬</span></div>
        <div class="metric-value">${AppState.buyers.length} Clients</div>
        <div class="metric-sub">US, EU, UK & Australian Markets</div>
      </div>
      <div class="metric-card">
        <div class="metric-header"><span class="metric-label">Approved Credit Facility</span><span>💳</span></div>
        <div class="metric-value">$${(totalCreditUSD / 1000).toFixed(0)}k USD</div>
        <div class="metric-sub">Insured under ECGC Credit Policy</div>
      </div>
      <div class="metric-card">
        <div class="metric-header"><span class="metric-label">Current Outstanding Balance</span><span>⏳</span></div>
        <div class="metric-value" style="color: var(--warning);">$${(totalOutstandingUSD / 1000).toFixed(1)}k USD</div>
        <div class="metric-sub">Within Payment Term Cycles</div>
      </div>
      <div class="metric-card">
        <div class="metric-header"><span class="metric-label">Payment Realization Rate</span><span>🏦</span></div>
        <div class="metric-value" style="color: var(--success);">99.2%</div>
        <div class="metric-sub">Zero Bad Debts Recorded</div>
      </div>
    </div>

    <!-- Table Toolbar -->
    <div class="table-toolbar-box">
      <div class="table-toolbar-left">
        <div class="table-search-input-wrap">
          <span class="table-search-icon">🔍</span>
          <input type="text" placeholder="Search by Buyer Code, Name, Country..." value="${f.search}" oninput="setTableSearch('buyers', this.value)">
        </div>
        <select class="table-filter-select" onchange="setTableFilter('buyers', 'tier', this.value)">
          <option value="all">All Buyer Tiers</option>
          <option value="Enterprise">Tier 1 Enterprise Retailer</option>
          <option value="Luxury">Luxury Home Retailer</option>
          <option value="Architectural">Architectural / Interior Trade</option>
          <option value="Wholesaler">European Wholesaler</option>
        </select>
      </div>
      <div class="table-toolbar-right">
        <button class="btn btn-sm btn-primary" onclick="openAddBuyerModal()">+ Add Buyer</button>
      </div>
    </div>

    <!-- Data Table -->
    <div class="card">
      <div class="table-responsive">
        <table class="data-table">
          <thead>
            <tr>
              <th class="sortable" onclick="setTableSort('buyers', 'name')">Buyer Legal Name & Code ${f.sortBy === 'name' ? (f.sortOrder === 'asc' ? '▲' : '▼') : ''}</th>
              <th>Country & Discharge Port</th>
              <th>Buyer Tier</th>
              <th>Payment Terms</th>
              <th>Credit Limit ($)</th>
              <th>Outstanding ($)</th>
              <th>Authorised Dealer Bank Branch</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            ${pagination.items.map(b => `
              <tr>
                <td>
                  <strong>${b.name}</strong>
                  <div style="font-size: 11px; font-family: var(--font-mono); color: var(--brand-cyan);">${b.code}</div>
                </td>
                <td>
                  <div>${b.country} (${b.city})</div>
                  <div style="font-size: 10px; color: var(--text-dim); font-family: var(--font-mono);">Port: ${b.preferredPort}</div>
                </td>
                <td><span class="badge badge-primary">${b.tier}</span></td>
                <td><strong style="color: var(--text-main); font-size: 12px;">${b.paymentTerms}</strong></td>
                <td><span style="font-family: var(--font-mono); font-weight: 700;">$${b.creditLimitUSD.toLocaleString()}</span></td>
                <td><span style="font-family: var(--font-mono); color: ${b.outstandingUSD > 0 ? 'var(--warning)' : 'var(--success)'}; font-weight: 700;">$${b.outstandingUSD.toLocaleString()}</span></td>
                <td><span style="font-size: 11px; color: var(--text-muted);">${b.adBankBranch}</span></td>
                <td>
                  <div class="row-actions-group">
                    <button class="btn-icon-action" title="Edit Buyer" onclick="openEditBuyerModal('${b.code}')">✏️</button>
                    <button class="btn-icon-action delete" title="Delete Buyer" onclick="confirmDeleteBuyer('${b.code}')">🗑️</button>
                  </div>
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>

      <!-- Pagination Footer -->
      <div class="table-pagination-footer">
        <div class="pagination-info">
          Showing <strong>${pagination.items.length ? pagination.start : 0}</strong> to <strong>${pagination.end}</strong> of <strong>${pagination.total}</strong> B2B buyer accounts
        </div>
        <div class="pagination-controls">
          <select class="rows-per-page-select" onchange="setTablePageSize('buyers', this.value)">
            <option value="5" ${(f.pageSize || 5) === 5 ? 'selected' : ''}>5 per page</option>
            <option value="10" ${(f.pageSize || 5) === 10 ? 'selected' : ''}>10 per page</option>
            <option value="25" ${(f.pageSize || 5) === 25 ? 'selected' : ''}>25 per page</option>
          </select>
          <button class="page-btn" ${pagination.currentPage === 1 ? 'disabled' : ''} onclick="setTablePage('buyers', ${pagination.currentPage - 1})">◀</button>
          ${Array.from({ length: pagination.totalPages }, (_, i) => i + 1).map(p => `
            <button class="page-btn ${p === pagination.currentPage ? 'active' : ''}" onclick="setTablePage('buyers', ${p})">${p}</button>
          `).join('')}
          <button class="page-btn" ${pagination.currentPage === pagination.totalPages ? 'disabled' : ''} onclick="setTablePage('buyers', ${pagination.currentPage + 1})">▶</button>
        </div>
      </div>
    </div>
  `;
}

function openAddBuyerModal() {
  const modal = document.getElementById("crudModal");
  const title = document.getElementById("crudModalTitle");
  const badge = document.getElementById("crudBadge");
  const body = document.getElementById("crudModalBody");
  const footer = document.getElementById("crudModalFooter");

  badge.textContent = "New Buyer";
  title.textContent = "Register International B2B Buyer (Module 2)";
  body.innerHTML = `
    <div class="form-grid-2">
      <div class="form-group">
        <label>Buyer Code (Unique ID):</label>
        <input type="text" class="form-control" id="buyerCode" placeholder="e.g. BUY-TARGET-US">
      </div>
      <div class="form-group">
        <label>Legal Company Name:</label>
        <input type="text" class="form-control" id="buyerName" placeholder="e.g. Target Corporation">
      </div>
    </div>
    <div class="form-grid-2">
      <div class="form-group">
        <label>Country / Destination:</label>
        <input type="text" class="form-control" id="buyerCountry" placeholder="e.g. United States">
      </div>
      <div class="form-group">
        <label>City & Head Office:</label>
        <input type="text" class="form-control" id="buyerCity" placeholder="e.g. Minneapolis, MN">
      </div>
    </div>
    <div class="form-grid-2">
      <div class="form-group">
        <label>Approved Payment Terms:</label>
        <select class="form-control" id="buyerTerms">
          <option>Net-60 Days (Direct ACH)</option>
          <option>Net-45 Days (EFT Wire)</option>
          <option>LC at Sight (Irrevocable)</option>
          <option>CAD (Cash Against Documents)</option>
          <option>50% Advance / 50% Against B/L</option>
        </select>
      </div>
      <div class="form-group">
        <label>Credit Limit (USD):</label>
        <input type="number" class="form-control" id="buyerCredit" value="200000">
      </div>
    </div>
    <div class="form-grid-2">
      <div class="form-group">
        <label>International SWIFT / Routing Code:</label>
        <input type="text" class="form-control" id="buyerSwift" placeholder="e.g. CHASUS33 / BOFAUS3N" value="CHASUS33">
      </div>
      <div class="form-group">
        <label>Designated Discharge Port:</label>
        <input type="text" class="form-control" id="buyerPort" placeholder="e.g. USNYC / USLAX" value="USNYC">
      </div>
    </div>
  `;
  footer.innerHTML = `
    <button class="btn btn-secondary" onclick="closeModal('crudModal')">Cancel</button>
    <button class="btn btn-primary" onclick="saveNewBuyer()">Save B2B Buyer</button>
  `;
  modal.style.display = "flex";
}

function saveNewBuyer() {
  const code = document.getElementById("buyerCode").value.trim() || `BUY-${Date.now().toString().slice(-4)}`;
  const name = document.getElementById("buyerName").value.trim() || "New Global Buyer";
  const country = document.getElementById("buyerCountry").value.trim() || "United States";
  const city = document.getElementById("buyerCity").value.trim() || "New York";
  const paymentTerms = document.getElementById("buyerTerms").value;
  const creditLimitUSD = parseFloat(document.getElementById("buyerCredit").value) || 100000;
  const swiftCode = document.getElementById("buyerSwift") ? document.getElementById("buyerSwift").value : "CHASUS33";

  AppState.buyers.unshift({
    code,
    name,
    tier: "Enterprise Retailer",
    country,
    city,
    paymentTerms,
    creditLimitUSD,
    outstandingUSD: 0,
    activeOrders: 0,
    preferredPort: "USNYC",
    swiftCode,
    contactPerson: "Operations Lead",
    email: "procurement@client.com",
    taxId: "EIN-PENDING",
    status: "Active / Approved"
  });

  closeModal("crudModal");
  showToast(`Buyer ${name} (${code}) added successfully!`, "success");
  renderCurrentView();
}

function openEditBuyerModal(code) {
  const b = AppState.buyers.find(item => item.code === code);
  if (!b) return;

  const modal = document.getElementById("crudModal");
  const title = document.getElementById("crudModalTitle");
  const badge = document.getElementById("crudBadge");
  const body = document.getElementById("crudModalBody");
  const footer = document.getElementById("crudModalFooter");

  badge.textContent = "Edit Buyer";
  title.textContent = `Edit Buyer: ${b.name}`;
  body.innerHTML = `
    <div class="form-grid-2">
      <div class="form-group">
        <label>Payment Terms:</label>
        <select class="form-control" id="editBuyerTerms">
          <option ${b.paymentTerms.includes('Net-60') ? 'selected' : ''}>Net-60 Days (Direct ACH)</option>
          <option ${b.paymentTerms.includes('Net-45') ? 'selected' : ''}>Net-45 Days (EFT Wire)</option>
          <option ${b.paymentTerms.includes('LC') ? 'selected' : ''}>LC at Sight (Irrevocable)</option>
          <option ${b.paymentTerms.includes('CAD') ? 'selected' : ''}>CAD (Cash Against Documents)</option>
          <option ${b.paymentTerms.includes('Advance') ? 'selected' : ''}>50% Advance / 50% Against B/L</option>
        </select>
      </div>
      <div class="form-group">
        <label>Credit Limit (USD):</label>
        <input type="number" class="form-control" id="editBuyerCredit" value="${b.creditLimitUSD}">
      </div>
    </div>
  `;
  footer.innerHTML = `
    <button class="btn btn-secondary" onclick="closeModal('crudModal')">Cancel</button>
    <button class="btn btn-primary" onclick="updateBuyer('${b.code}')">Update Buyer</button>
  `;
  modal.style.display = "flex";
}

function updateBuyer(code) {
  const b = AppState.buyers.find(item => item.code === code);
  if (!b) return;

  b.paymentTerms = document.getElementById("editBuyerTerms").value;
  b.creditLimitUSD = parseFloat(document.getElementById("editBuyerCredit").value) || b.creditLimitUSD;

  closeModal("crudModal");
  showToast(`Buyer ${b.name} updated!`, "success");
  renderCurrentView();
}

function confirmDeleteBuyer(code) {
  const modal = document.getElementById("deleteConfirmModal");
  const msg = document.getElementById("deleteModalMessage");
  const btn = document.getElementById("confirmDeleteBtn");

  msg.textContent = `Are you sure you want to delete buyer account ${code}?`;
  btn.onclick = () => {
    AppState.buyers = AppState.buyers.filter(b => b.code !== code);
    closeModal("deleteConfirmModal");
    showToast(`Buyer ${code} removed.`, "danger");
    renderCurrentView();
  };
  modal.style.display = "flex";
}

function exportBuyersCSV() {
  let csv = "Buyer Code,Legal Name,Tier,Country,City,Payment Terms,Credit Limit USD,Outstanding USD,AD Bank Branch\n";
  AppState.buyers.forEach(b => {
    csv += `"${b.code}","${b.name}","${b.tier}","${b.country}","${b.city}","${b.paymentTerms}",${b.creditLimitUSD},${b.outstandingUSD},"${b.adBankBranch}"\n`;
  });
  triggerDownload("RugOS_Buyers_Master.csv", csv, "text/csv");
}

// --- ARTISAN & LOOM MASTER ---
function renderLoomsMasterView() {
  const f = AppState.tableFilters.looms || { search: "", type: "all", sortBy: "loomId", sortOrder: "asc", page: 1, pageSize: 5 };
  let filtered = AppState.looms.filter(l => {
    const matchesSearch = !f.search || l.loomId.toLowerCase().includes(f.search) || l.masterWeaver.toLowerCase().includes(f.search) || l.facility.toLowerCase().includes(f.search);
    const matchesType = f.type === "all" || l.loomType.toLowerCase().includes(f.type.toLowerCase());
    return matchesSearch && matchesType;
  });

  const totalCapacitySqm = AppState.looms.reduce((sum, l) => sum + (l.monthlyCapacitySqm || 0), 0);
  const pagination = paginateArray(filtered, f.page || 1, f.pageSize || 5);

  return `
    <div class="page-header">
      <div class="page-title-wrap">
        <h1>🪡 Artisan & Loom Master (Manufacturing Stations)</h1>
        <p>Station-by-station governance across Bhadohi, Mirzapur, Gopiganj, Jaipur, and Panipat carpet weaving centers.</p>
      </div>
      <div class="page-actions">
        <button class="btn btn-secondary" onclick="exportLoomsCSV()">📥 Export Looms CSV</button>
        <button class="btn btn-primary" onclick="openAddLoomModal()">+ Add Production Loom</button>
      </div>
    </div>

    
    <!-- Linked Raw Materials Inventory Section -->
    <div class="card" style="margin-bottom: 20px;">
      <div class="card-header" style="display: flex; justify-content: space-between; align-items: center;">
        <div class="card-title-group">
          <h3>🧶 Loom Raw Materials & Dye Lots In-Stock</h3>
          <p>Real-time spool inventory available for BOM issuance across Bhadohi, Mirzapur & Jaipur looms</p>
        </div>
        <button class="btn btn-sm btn-primary" onclick="showToast('AI Loom Yarn Allocation: Wool and Silk spools reserved for active MTO jobs.', 'success')">💡 Suggest Loom Yarn Replenishment</button>
      </div>
      <div class="card-body">
        <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px;">
          ${(AppState.rawMaterials || []).map(mat => `
            <div style="border: 1px solid var(--border-main); border-radius: var(--radius-md); padding: 12px; background: var(--bg-app);">
              <div style="font-size: 11px; font-family: var(--font-mono); color: var(--brand-cyan);">${mat.lot}</div>
              <strong style="font-size: 13px; display: block; margin: 4px 0;">${mat.material}</strong>
              <div style="font-size: 11px; color: var(--text-dim); margin-bottom: 8px;">Origin: ${mat.origin}</div>
              <div style="display: flex; justify-content: space-between; font-size: 12px; border-top: 1px solid var(--border-subtle); padding-top: 6px;">
                <span>In Stock:</span>
                <strong style="color: var(--success);">${mat.stockKg} kg</strong>
              </div>
              <div style="display: flex; justify-content: space-between; font-size: 11px; color: var(--text-muted);">
                <span>Allocated:</span>
                <span>${mat.allocatedKg} kg</span>
              </div>
            </div>
          `).join('')}
        </div>
      </div>
    </div>

    ${renderBlueprintSpec("Module 2 — Loom Station & Artisan Profile Governance (40 hrs)", "Allocates raw wool spools and custom CAD stencils to Aadhaar-verified master weavers. Manages Direct Benefit Transfer (DBT) artisan wage milestone payouts.")}

    <!-- Bento KPI Metrics -->
    <div class="bento-metrics-grid" style="grid-template-columns: repeat(4, 1fr); margin-bottom: 20px;">
      <div class="metric-card">
        <div class="metric-header"><span class="metric-label">Active Loom Stations</span><span>🪡</span></div>
        <div class="metric-value">${AppState.looms.length} Stations</div>
        <div class="metric-sub">Hand-Knotted, Tufted & Flatweave</div>
      </div>
      <div class="metric-card">
        <div class="metric-header"><span class="metric-label">Monthly Weaving Capacity</span><span>📐</span></div>
        <div class="metric-value">${totalCapacitySqm} sq.m</div>
        <div class="metric-sub">Across All 5 Regional Clusters</div>
      </div>
      <div class="metric-card">
        <div class="metric-header"><span class="metric-label">Aadhaar Verified Artisans</span><span>🪪</span></div>
        <div class="metric-value" style="color: var(--success);">100% Verified</div>
        <div class="metric-sub">DBT Direct Bank Payment Linked</div>
      </div>
      <div class="metric-card">
        <div class="metric-header"><span class="metric-label">Child Labor Free Certification</span><span>🏅</span></div>
        <div class="metric-value" style="color: var(--brand-cyan);">GoodWeave Standard</div>
        <div class="metric-sub">Surprise Inspection Verified</div>
      </div>
    </div>

    <!-- Table Toolbar -->
    <div class="table-toolbar-box">
      <div class="table-toolbar-left">
        <div class="table-search-input-wrap">
          <span class="table-search-icon">🔍</span>
          <input type="text" placeholder="Search by Loom ID, Master Weaver, Cluster..." value="${f.search}" oninput="setTableSearch('looms', this.value)">
        </div>
        <select class="table-filter-select" onchange="setTableFilter('looms', 'type', this.value)">
          <option value="all">All Loom Types</option>
          <option value="Knotted">Hand-Knotted Pit Loom</option>
          <option value="Tufted">Hand-Tufted 60-Needle Frame</option>
          <option value="Flatweave">Flatweave Dhurrie Loom</option>
          <option value="Braid">Jute Braiding & Stitch Table</option>
        </select>
      </div>
      <div class="table-toolbar-right">
        <button class="btn btn-sm btn-primary" onclick="openAddLoomModal()">+ Add Loom Station</button>
      </div>
    </div>

    <!-- Data Table -->
    <div class="card">
      <div class="table-responsive">
        <table class="data-table">
          <thead>
            <tr>
              <th>Loom ID & Facility</th>
              <th>Loom Construction Type</th>
              <th>Master Weaver Lead</th>
              <th>Max Width (Ft)</th>
              <th>Monthly Output</th>
              <th>Active MTO Job</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            ${pagination.items.map(l => `
              <tr>
                <td>
                  <strong style="font-family: var(--font-mono); color: var(--brand-cyan);">${l.loomId}</strong>
                  <div style="font-size: 11px; color: var(--text-dim);">${l.facility} (${l.village})</div>
                </td>
                <td>
                  <div>${l.loomType}</div>
                  <div style="font-size: 10px; color: var(--brand-cyan);">${l.rating}</div>
                </td>
                <td>
                  <strong>${l.masterWeaver}</strong>
                  <div style="font-size: 11px; color: var(--text-muted);">${l.craftGrade}</div>
                </td>
                <td><span style="font-weight: 700;">${l.maxWidthFt} ft</span></td>
                <td><span style="font-family: var(--font-mono);">${l.monthlyCapacitySqm} sq.m</span></td>
                <td><code>${l.activeJobId || 'Idle / Open'}</code></td>
                <td><span class="badge ${l.status.includes('Active') ? 'badge-success' : 'badge-warning'}">${l.status}</span></td>
                <td>
                  <div class="row-actions-group">
                    <button class="btn-icon-action" title="Edit Loom" onclick="openEditLoomModal('${l.loomId}')">✏️</button>
                    <button class="btn-icon-action delete" title="Delete Loom" onclick="confirmDeleteLoom('${l.loomId}')">🗑️</button>
                  </div>
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>

      <!-- Pagination Footer -->
      <div class="table-pagination-footer">
        <div class="pagination-info">
          Showing <strong>${pagination.items.length ? pagination.start : 0}</strong> to <strong>${pagination.end}</strong> of <strong>${pagination.total}</strong> production loom stations
        </div>
        <div class="pagination-controls">
          <select class="rows-per-page-select" onchange="setTablePageSize('looms', this.value)">
            <option value="5" ${(f.pageSize || 5) === 5 ? 'selected' : ''}>5 per page</option>
            <option value="10" ${(f.pageSize || 5) === 10 ? 'selected' : ''}>10 per page</option>
            <option value="25" ${(f.pageSize || 5) === 25 ? 'selected' : ''}>25 per page</option>
          </select>
          <button class="page-btn" ${pagination.currentPage === 1 ? 'disabled' : ''} onclick="setTablePage('looms', ${pagination.currentPage - 1})">◀</button>
          ${Array.from({ length: pagination.totalPages }, (_, i) => i + 1).map(p => `
            <button class="page-btn ${p === pagination.currentPage ? 'active' : ''}" onclick="setTablePage('looms', ${p})">${p}</button>
          `).join('')}
          <button class="page-btn" ${pagination.currentPage === pagination.totalPages ? 'disabled' : ''} onclick="setTablePage('looms', ${pagination.currentPage + 1})">▶</button>
        </div>
      </div>
    </div>
  `;
}

function openAddLoomModal() {
  const modal = document.getElementById("crudModal");
  const title = document.getElementById("crudModalTitle");
  const badge = document.getElementById("crudBadge");
  const body = document.getElementById("crudModalBody");
  const footer = document.getElementById("crudModalFooter");

  badge.textContent = "New Loom";
  title.textContent = "Add Artisan Production Loom Station";
  body.innerHTML = `
    <div class="form-grid-2">
      <div class="form-group">
        <label>Loom Identifier (ID):</label>
        <input type="text" class="form-control" id="loomIdInput" placeholder="e.g. LOOM-BHD-P11">
      </div>
      <div class="form-group">
        <label>Manufacturing Facility / Village:</label>
        <input type="text" class="form-control" id="loomFacility" placeholder="e.g. Khamaria Village, Bhadohi">
      </div>
    </div>
    <div class="form-grid-2">
      <div class="form-group">
        <label>Loom Construction Type:</label>
        <select class="form-control" id="loomTypeSelect">
          <option>Hand-Knotted Pit Loom (Double Warp)</option>
          <option>Hand-Tufted 60-Needle Pneumatic Frame</option>
          <option>Interlocking Flatweave Dhurrie Loom</option>
          <option>Tension Flat Braid & Stitch Table</option>
        </select>
      </div>
      <div class="form-group">
        <label>Max Weaving Width (Feet):</label>
        <input type="number" class="form-control" id="loomWidth" value="14.0">
      </div>
    </div>
    <div class="form-grid-2">
      <div class="form-group">
        <label>Master Weaver Name:</label>
        <input type="text" class="form-control" id="loomWeaver" placeholder="e.g. Mohammad Aslam">
      </div>
      <div class="form-group">
        <label>Monthly Capacity (sq.m):</label>
        <input type="number" class="form-control" id="loomCap" value="50">
      </div>
    </div>
  `;
  footer.innerHTML = `
    <button class="btn btn-secondary" onclick="closeModal('crudModal')">Cancel</button>
    <button class="btn btn-primary" onclick="saveNewLoom()">Save Loom Station</button>
  `;
  modal.style.display = "flex";
}

function saveNewLoom() {
  const loomId = document.getElementById("loomIdInput").value.trim() || `LOOM-${Date.now().toString().slice(-4)}`;
  const facility = document.getElementById("loomFacility").value.trim() || "Bhadohi Central Hub";
  const loomType = document.getElementById("loomTypeSelect").value;
  const maxWidthFt = parseFloat(document.getElementById("loomWidth").value) || 12.0;
  const masterWeaver = document.getElementById("loomWeaver").value.trim() || "Artisan Lead";
  const monthlyCapacitySqm = parseInt(document.getElementById("loomCap").value) || 40;

  AppState.looms.unshift({
    loomId,
    facility,
    village: "Bhadohi District",
    loomType,
    maxWidthFt,
    masterWeaver,
    aadhaarVerified: true,
    craftGrade: "Senior Artisan",
    monthlyCapacitySqm,
    activeJobId: "Idle",
    status: "Available / Idle",
    dbtBankAc: "Direct Bank Transfer Active",
    rating: "4.9 ★"
  });

  closeModal("crudModal");
  showToast(`Loom station ${loomId} added!`, "success");
  renderCurrentView();
}

function openEditLoomModal(loomId) {
  const l = AppState.looms.find(item => item.loomId === loomId);
  if (!l) return;

  const modal = document.getElementById("crudModal");
  const title = document.getElementById("crudModalTitle");
  const badge = document.getElementById("crudBadge");
  const body = document.getElementById("crudModalBody");
  const footer = document.getElementById("crudModalFooter");

  badge.textContent = "Edit Loom";
  title.textContent = `Edit Loom: ${l.loomId}`;
  body.innerHTML = `
    <div class="form-grid-2">
      <div class="form-group">
        <label>Master Weaver Lead:</label>
        <input type="text" class="form-control" id="editLoomWeaver" value="${l.masterWeaver}">
      </div>
      <div class="form-group">
        <label>Status:</label>
        <select class="form-control" id="editLoomStatus">
          <option ${l.status.includes('Active') ? 'selected' : ''}>In Active Weaving</option>
          <option ${l.status.includes('Washing') ? 'selected' : ''}>Washing & Sun Deck QC</option>
          <option ${l.status.includes('Available') ? 'selected' : ''}>Available / Idle</option>
        </select>
      </div>
    </div>
  `;
  footer.innerHTML = `
    <button class="btn btn-secondary" onclick="closeModal('crudModal')">Cancel</button>
    <button class="btn btn-primary" onclick="updateLoom('${l.loomId}')">Update Loom</button>
  `;
  modal.style.display = "flex";
}

function updateLoom(loomId) {
  const l = AppState.looms.find(item => item.loomId === loomId);
  if (!l) return;

  l.masterWeaver = document.getElementById("editLoomWeaver").value;
  l.status = document.getElementById("editLoomStatus").value;

  closeModal("crudModal");
  showToast(`Loom ${loomId} updated!`, "success");
  renderCurrentView();
}

function confirmDeleteLoom(loomId) {
  const modal = document.getElementById("deleteConfirmModal");
  const msg = document.getElementById("deleteModalMessage");
  const btn = document.getElementById("confirmDeleteBtn");

  msg.textContent = `Are you sure you want to delete loom station ${loomId}?`;
  btn.onclick = () => {
    AppState.looms = AppState.looms.filter(l => l.loomId !== loomId);
    closeModal("deleteConfirmModal");
    showToast(`Loom ${loomId} removed.`, "danger");
    renderCurrentView();
  };
  modal.style.display = "flex";
}

function exportLoomsCSV() {
  let csv = "Loom ID,Facility,Village,Loom Type,Max Width Ft,Master Weaver,Monthly Capacity Sqm,Status\n";
  AppState.looms.forEach(l => {
    csv += `"${l.loomId}","${l.facility}","${l.village}","${l.loomType}",${l.maxWidthFt},"${l.masterWeaver}",${l.monthlyCapacitySqm},"${l.status}"\n`;
  });
  triggerDownload("RugOS_Loom_Master.csv", csv, "text/csv");
}

// --- FREIGHT & CARRIER MASTER ---
function renderCarriersMasterView() {
  const f = AppState.tableFilters.carriers || { search: "", mode: "all", sortBy: "name", sortOrder: "asc", page: 1, pageSize: 5 };
  let filtered = AppState.carriers.filter(c => {
    const matchesSearch = !f.search || c.name.toLowerCase().includes(f.search) || c.code.toLowerCase().includes(f.search) || c.accountNo.toLowerCase().includes(f.search);
    const matchesMode = f.mode === "all" || c.mode.toLowerCase().includes(f.mode.toLowerCase());
    return matchesSearch && matchesMode;
  });

  const pagination = paginateArray(filtered, f.page || 1, f.pageSize || 5);

  return `
    <div class="page-header">
      <div class="page-title-wrap">
        <h1>🚢 Freight Forwarder & Carrier Master</h1>
        <p>Contractual freight rate agreements, volumetric divisor rules (5000 vs 6000), and automated EDI tracking integrations.</p>
      </div>
      <div class="page-actions">
        <button class="btn btn-secondary" onclick="exportCarriersCSV()">📥 Export Carriers CSV</button>
        <button class="btn btn-primary" onclick="openAddCarrierModal()">+ Add Freight Carrier</button>
      </div>
    </div>

    ${renderBlueprintSpec("Module 2 — Global Logistics Carrier Governance (35 hrs)", "Defines dimensional catch-weight rules across air express (FedEx/DHL) and ocean freight (Maersk/MSC) with automated 3-way invoice matching.")}

    <!-- Table Toolbar -->
    <div class="table-toolbar-box">
      <div class="table-toolbar-left">
        <div class="table-search-input-wrap">
          <span class="table-search-icon">🔍</span>
          <input type="text" placeholder="Search carrier name, code, account #..." value="${f.search}" oninput="setTableSearch('carriers', this.value)">
        </div>
        <select class="table-filter-select" onchange="setTableFilter('carriers', 'mode', this.value)">
          <option value="all">All Transit Modes</option>
          <option value="Air">International Air Courier</option>
          <option value="Ocean">Ocean FCL & LCL Freight</option>
          <option value="Rail">Bonded ICD Rail Link</option>
        </select>
      </div>
      <div class="table-toolbar-right">
        <button class="btn btn-sm btn-primary" onclick="openAddCarrierModal()">+ Add Carrier</button>
      </div>
    </div>

    <!-- Data Table -->
    <div class="card">
      <div class="table-responsive">
        <table class="data-table">
          <thead>
            <tr>
              <th>Carrier Code & Name</th>
              <th>Transit Mode</th>
              <th>Account / Contract #</th>
              <th>Volumetric Divisor</th>
              <th>Catch-Weight Reconciliation Rule</th>
              <th>Preferred Export Gateway</th>
              <th>Avg SLA</th>
              <th>API Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            ${pagination.items.map(c => `
              <tr>
                <td>
                  <strong>${c.name}</strong>
                  <div style="font-size: 11px; font-family: var(--font-mono); color: var(--brand-cyan);">${c.code}</div>
                </td>
                <td><span class="badge ${c.mode.includes('Air') ? 'badge-primary' : 'badge-success'}">${c.mode}</span></td>
                <td><code>${c.accountNo}</code></td>
                <td><strong style="font-family: var(--font-mono); font-size: 14px;">${c.volDivisor}</strong></td>
                <td><span style="font-size: 11px; color: var(--text-muted);">${c.catchWeightAuditRule}</span></td>
                <td><span style="font-size: 11px; color: var(--text-main); font-weight: 600;">${c.preferredPort}</span></td>
                <td><span style="font-size: 11px;">${c.avgTransitDays}</span></td>
                <td><span class="badge badge-success">${c.apiStatus.split(' ')[0]}</span></td>
                <td>
                  <div class="row-actions-group">
                    <button class="btn-icon-action" title="Edit Carrier" onclick="openEditCarrierModal('${c.code}')">✏️</button>
                    <button class="btn-icon-action delete" title="Delete Carrier" onclick="confirmDeleteCarrier('${c.code}')">🗑️</button>
                  </div>
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>

      <!-- Pagination Footer -->
      <div class="table-pagination-footer">
        <div class="pagination-info">
          Showing <strong>${pagination.items.length ? pagination.start : 0}</strong> to <strong>${pagination.end}</strong> of <strong>${pagination.total}</strong> freight carriers
        </div>
        <div class="pagination-controls">
          <select class="rows-per-page-select" onchange="setTablePageSize('carriers', this.value)">
            <option value="5" ${(f.pageSize || 5) === 5 ? 'selected' : ''}>5 per page</option>
            <option value="10" ${(f.pageSize || 5) === 10 ? 'selected' : ''}>10 per page</option>
          </select>
          <button class="page-btn" ${pagination.currentPage === 1 ? 'disabled' : ''} onclick="setTablePage('carriers', ${pagination.currentPage - 1})">◀</button>
          ${Array.from({ length: pagination.totalPages }, (_, i) => i + 1).map(p => `
            <button class="page-btn ${p === pagination.currentPage ? 'active' : ''}" onclick="setTablePage('carriers', ${p})">${p}</button>
          `).join('')}
          <button class="page-btn" ${pagination.currentPage === pagination.totalPages ? 'disabled' : ''} onclick="setTablePage('carriers', ${pagination.currentPage + 1})">▶</button>
        </div>
      </div>
    </div>
  `;
}

function openAddCarrierModal() {
  const modal = document.getElementById("crudModal");
  const title = document.getElementById("crudModalTitle");
  const badge = document.getElementById("crudBadge");
  const body = document.getElementById("crudModalBody");
  const footer = document.getElementById("crudModalFooter");

  badge.textContent = "New Carrier";
  title.textContent = "Configure Freight Carrier & Tariff Card";
  body.innerHTML = `
    <div class="form-grid-2">
      <div class="form-group">
        <label>Carrier Code:</label>
        <input type="text" class="form-control" id="carrierCode" placeholder="e.g. CRR-UPS-AIR">
      </div>
      <div class="form-group">
        <label>Carrier Entity Name:</label>
        <input type="text" class="form-control" id="carrierName" placeholder="e.g. UPS Worldwide Express">
      </div>
    </div>
    <div class="form-grid-2">
      <div class="form-group">
        <label>Transit Mode:</label>
        <select class="form-control" id="carrierMode">
          <option>International Air Courier</option>
          <option>Ocean FCL & LCL Freight</option>
          <option>Bonded ICD Rail Link</option>
        </select>
      </div>
      <div class="form-group">
        <label>Volumetric Divisor:</label>
        <select class="form-control" id="carrierDivisor">
          <option value="5000">5000 (IATA International Air Standard)</option>
          <option value="6000">6000 (Domestic Rail/Surface Standard)</option>
          <option value="1000">1000 (Ocean CBM Standard)</option>
        </select>
      </div>
    </div>
    <div class="form-grid-2">
      <div class="form-group">
        <label>Contract / Account Number:</label>
        <input type="text" class="form-control" id="carrierAccount" placeholder="e.g. UPS-BHD-99014">
      </div>
      <div class="form-group">
        <label>Preferred Port Gateway:</label>
        <input type="text" class="form-control" id="carrierPort" value="DEL / INNSA1">
      </div>
    </div>
  `;
  footer.innerHTML = `
    <button class="btn btn-secondary" onclick="closeModal('crudModal')">Cancel</button>
    <button class="btn btn-primary" onclick="saveNewCarrier()">Save Carrier</button>
  `;
  modal.style.display = "flex";
}

function saveNewCarrier() {
  const code = document.getElementById("carrierCode").value.trim() || `CRR-${Date.now().toString().slice(-4)}`;
  const name = document.getElementById("carrierName").value.trim() || "New Freight Forwarder";
  const mode = document.getElementById("carrierMode").value;
  const volDivisor = parseInt(document.getElementById("carrierDivisor").value) || 5000;
  const accountNo = document.getElementById("carrierAccount").value.trim() || "ACC-PENDING";
  const preferredPort = document.getElementById("carrierPort").value.trim() || "DEL";

  AppState.carriers.unshift({
    code,
    name,
    mode,
    accountNo,
    volDivisor,
    catchWeightAuditRule: "Actual vs Volumetric whichever is greater",
    preferredPort,
    avgTransitDays: "3-5 Days",
    apiStatus: "Connected",
    reconciliationAuto: true,
    monthlyBillingUSD: 10000
  });

  closeModal("crudModal");
  showToast(`Carrier ${name} (${code}) configured!`, "success");
  renderCurrentView();
}

function openEditCarrierModal(code) {
  const c = AppState.carriers.find(item => item.code === code);
  if (!c) return;

  const modal = document.getElementById("crudModal");
  const title = document.getElementById("crudModalTitle");
  const badge = document.getElementById("crudBadge");
  const body = document.getElementById("crudModalBody");
  const footer = document.getElementById("crudModalFooter");

  badge.textContent = "Edit Carrier";
  title.textContent = `Edit Carrier: ${c.name}`;
  body.innerHTML = `
    <div class="form-group">
      <label>Contract Account Number:</label>
      <input type="text" class="form-control" id="editCarrierAccount" value="${c.accountNo}">
    </div>
    <div class="form-group">
      <label>Volumetric Divisor:</label>
      <input type="number" class="form-control" id="editCarrierDivisor" value="${c.volDivisor}">
    </div>
  `;
  footer.innerHTML = `
    <button class="btn btn-secondary" onclick="closeModal('crudModal')">Cancel</button>
    <button class="btn btn-primary" onclick="updateCarrier('${c.code}')">Update Carrier</button>
  `;
  modal.style.display = "flex";
}

function updateCarrier(code) {
  const c = AppState.carriers.find(item => item.code === code);
  if (!c) return;

  c.accountNo = document.getElementById("editCarrierAccount").value;
  c.volDivisor = parseInt(document.getElementById("editCarrierDivisor").value) || c.volDivisor;

  closeModal("crudModal");
  showToast(`Carrier ${c.name} updated!`, "success");
  renderCurrentView();
}

function confirmDeleteCarrier(code) {
  const modal = document.getElementById("deleteConfirmModal");
  const msg = document.getElementById("deleteModalMessage");
  const btn = document.getElementById("confirmDeleteBtn");

  msg.textContent = `Are you sure you want to delete carrier ${code}?`;
  btn.onclick = () => {
    AppState.carriers = AppState.carriers.filter(c => c.code !== code);
    closeModal("deleteConfirmModal");
    showToast(`Carrier ${code} removed.`, "danger");
    renderCurrentView();
  };
  modal.style.display = "flex";
}

function exportCarriersCSV() {
  let csv = "Carrier Code,Name,Mode,Account No,Volumetric Divisor,Catch-Weight Rule,Preferred Port,API Status\n";
  AppState.carriers.forEach(c => {
    csv += `"${c.code}","${c.name}","${c.mode}","${c.accountNo}",${c.volDivisor},"${c.catchWeightAuditRule}","${c.preferredPort}","${c.apiStatus}"\n`;
  });
  triggerDownload("RugOS_Carrier_Master.csv", csv, "text/csv");
}

