function saveBankRealization(invoiceNo) {
  const r = AppState.receivables.find(item => item.invoiceNo === invoiceNo);
  if (r) {
    const usd = parseFloat(document.getElementById("wireAmountUSD").value) || r.amountUSD;
    const fx = parseFloat(document.getElementById("wireFxRate").value) || r.exchangeRateINR;
    const ebrc = document.getElementById("wireEbrcNo").value.trim();

    r.realizedINR += (usd * fx);
    r.balanceUSD = Math.max(0, r.balanceUSD - usd);
    r.status = r.balanceUSD === 0 ? "Paid & Realized" : "Partially Paid";
    r.ebrcNo = ebrc;

    closeModal("crudModal");
    showToast(`Bank inward remittance reconciled! e-BRC #${ebrc} issued and reported to RBI EDPMS.`, 'success');
    renderCurrentView();
  }
}


