function updateInwardPreview() {
  const skuSelect = document.getElementById("inwardSkuSelect");
  const qtyInput = document.getElementById("inwardQtyInput");
  const whSelect = document.getElementById("inwardWhSelect");
  const previewBox = document.getElementById("inwardPreviewBox");

  if (!skuSelect || !qtyInput || !previewBox) return;

  const skuCode = skuSelect.value;
  const qty = parseInt(qtyInput.value) || 0;
  const whId = whSelect ? whSelect.value : "WH-IND-01";

  const skuObj = AppState.skus.find(s => s.sku === skuCode) || AppState.skus[0];
  const whObj = AppState.warehouses.find(w => w.id === whId) || AppState.warehouses[0];

  const currentIndia = skuObj.stock.indiaAvailable || 0;
  const currentUSA = skuObj.stock.usaAvailable || 0;
  const currentFBA = skuObj.stock.fba || 0;
  const totalWeightKg = (qty * skuObj.weightKg).toFixed(1);
  const additionalValUSD = qty * skuObj.sellingPriceUSD;

  let targetField = "India Origin Available";
  let targetCurrent = currentIndia;
  if (whId.includes("USA-01") || whObj.name.includes("USA") || whObj.name.includes("Edison")) {
    targetField = "USA 3PL Edison NJ Stock";
    targetCurrent = currentUSA;
  } else if (whId.includes("USA-02") || whObj.name.includes("FBA") || whObj.name.includes("Dallas")) {
    targetField = "Amazon FBA Live Stock";
    targetCurrent = currentFBA;
  }

  previewBox.innerHTML = `
    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">
      <span style="font-weight: 700; font-size: 12px; color: var(--text-main);">📈 Projected Stock Ledger Impact:</span>
      <span class="badge badge-success">+${qty} Rolls Inward</span>
    </div>
    <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; font-size: 12px;">
      <div style="padding: 8px; background: rgba(255,255,255,0.02); border-radius: 4px; border: 1px solid var(--border-subtle);">
        <div style="color: var(--text-dim); font-size: 10px; text-transform: uppercase;">${targetField}</div>
        <div style="font-weight: 800; font-size: 15px; color: var(--brand-cyan); margin-top: 2px;">
          ${targetCurrent} ➔ <span style="color: var(--success);">${targetCurrent + qty}</span> Rolls
        </div>
      </div>
      <div style="padding: 8px; background: rgba(255,255,255,0.02); border-radius: 4px; border: 1px solid var(--border-subtle);">
        <div style="color: var(--text-dim); font-size: 10px; text-transform: uppercase;">Total Physical Weight</div>
        <div style="font-weight: 800; font-size: 15px; margin-top: 2px;">
          ${totalWeightKg} Kg
        </div>
      </div>
      <div style="padding: 8px; background: rgba(255,255,255,0.02); border-radius: 4px; border: 1px solid var(--border-subtle);">
        <div style="color: var(--text-dim); font-size: 10px; text-transform: uppercase;">Ledger Valuation Increase</div>
        <div style="font-weight: 800; font-size: 15px; color: var(--success); margin-top: 2px;">
          +$${additionalValUSD.toLocaleString()} USD
        </div>
      </div>
    </div>
  `;
}

function saveNewInventory() {
  const skuSelect = document.getElementById("inwardSkuSelect");
  const qtyInput = document.getElementById("inwardQtyInput");
  const whSelect = document.getElementById("inwardWhSelect");
  const binInput = document.getElementById("inwardBinInput");
  const sourceSelect = document.getElementById("inwardSourceType");
  const lotInput = document.getElementById("inwardLotRef");
  const poInput = document.getElementById("inwardPoRef");

  if (!skuSelect || !qtyInput) return;

  const skuCode = skuSelect.value;
  const qty = parseInt(qtyInput.value) || 0;
  const whId = whSelect ? whSelect.value : "WH-IND-01";
  const binCode = binInput ? binInput.value.trim() || "Zone A / Receiving Dock" : "Zone A / Receiving Dock";
  const sourceType = sourceSelect ? sourceSelect.value : "Finished Loom Production Arrival";
  const lotRef = lotInput ? lotInput.value.trim() || "LOT-GEN-2026" : "LOT-GEN-2026";
  const poRef = poInput ? poInput.value.trim() || "INW-2026" : "INW-2026";

  if (qty <= 0) {
    showToast("Please enter a valid quantity of at least 1 carpet roll.", "warning");
    return;
  }

  const skuObj = AppState.skus.find(s => s.sku === skuCode);
  if (!skuObj) {
    showToast("Error: Selected SKU not found in master catalog.", "danger");
    return;
  }

  const whObj = AppState.warehouses.find(w => w.id === whId) || AppState.warehouses[0];

  // Apply inward stock quantity to the appropriate facility
  if (whId.includes("USA-01") || whObj.name.includes("USA") || whObj.name.includes("Edison")) {
    skuObj.stock.usaAvailable = (skuObj.stock.usaAvailable || 0) + qty;
  } else if (whId.includes("USA-02") || whObj.name.includes("FBA") || whObj.name.includes("Dallas")) {
    skuObj.stock.fba = (skuObj.stock.fba || 0) + qty;
  } else {
    skuObj.stock.indiaAvailable = (skuObj.stock.indiaAvailable || 0) + qty;
  }

  // Record an immutable transaction entry into the SKU Movement History Ledger
  const nowStr = new Date().toISOString().replace('T', ' ').slice(0, 19);
  AppState.skuHistory.unshift({
    timestamp: nowStr,
    sku: skuObj.sku,
    type: "Inward Stock Receipt",
    qty: qty,
    source: sourceType,
    dest: `${whObj.name} (${binCode})`,
    user: "Admin / Management",
    ref: `${poRef} [${lotRef}]`
  });

  closeModal("crudModal");
  showToast(`Successfully inwarded ${qty} rolls of ${skuObj.sku} to ${whObj.name}!`, "success");
  renderCurrentView();
}

