function updateGrnModalPreview() {
  const skuSelect = document.getElementById("grnSkuSelect");
  const card = document.getElementById("grnStockPreviewCard");
  const qtyInput = document.getElementById("grnQty");
  if (!skuSelect || !card) return;

  const s = AppState.skus.find(item => item.sku === skuSelect.value) || AppState.skus[0];
  const transit = s.stock.inTransit || 0;
  if (qtyInput) {
    qtyInput.max = transit || 999;
    qtyInput.value = Math.min(transit, 20) || (transit > 0 ? transit : 5);
  }

  card.innerHTML = `
    <div style="display: flex; justify-content: space-between; align-items: center;">
      <div>
        <strong style="color: var(--brand-cyan); font-size: 13px;">${s.sku} — ${s.title}</strong>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">
          Size: ${s.size} • Weight: ${s.weightKg} kg/roll • Ocean Landed Freight: $${s.allocatedLandedFreightUSD}/Kg
        </div>
      </div>
      <div style="text-align: right;">
        <div style="font-size: 11px; color: var(--text-dim); text-transform: uppercase;">In-Transit (Ocean Vessel)</div>
        <div style="font-size: 20px; font-weight: 800; color: var(--warning);">${transit} Rolls</div>
      </div>
    </div>
    <div style="display: flex; gap: 16px; margin-top: 8px; font-size: 11px; padding-top: 8px; border-top: 1px solid var(--border-subtle); flex-wrap: wrap;">
      <span>Current USA 3PL Stock: <strong style="color: var(--success);">${s.stock.usaAvailable || 0} Rolls</strong></span>
      <span>Concurrency Locked: <strong style="color: var(--danger);">${s.stock.usaReserved || 0} Rolls</strong></span>
      <span>Amazon FBA: <strong style="color: var(--brand-cyan);">${s.stock.fba || 0} Rolls</strong></span>
    </div>
  `;
}

function executeReceiveInTransit() {
  const skuSelect = document.getElementById("grnSkuSelect");
  const whSelect = document.getElementById("grnWhSelect");
  const blRef = document.getElementById("grnBlRef").value.trim() || "BL-NYC-2026";
  const cbpRef = document.getElementById("grnCbpRef").value.trim() || "CBP-ENTRY-2026";
  const binLocation = document.getElementById("grnBinLocation").value.trim() || "Aisle 4 / High-Bay";
  const qty = parseInt(document.getElementById("grnQty").value) || 0;
  const isConfirmed = document.getElementById("grnScanConfirmed").checked;

  if (qty <= 0) {
    showToast("Please enter a valid quantity of received carpet rolls.", "warning");
    return;
  }
  if (!isConfirmed) {
    showToast("Physical barcode RF scanner verification must be checked to confirm dock receipt.", "warning");
    return;
  }

  const s = AppState.skus.find(item => item.sku === skuSelect.value);
  if (!s) return;

  const whId = whSelect.value;
  const whObj = AppState.warehouses.find(w => w.id === whId) || AppState.warehouses.find(w => w.id === "WH-USA-01") || { name: "USA 3PL Warehouse (Edison, NJ)" };

  // Transfer stock from inTransit to usaAvailable or fba
  const deductQty = Math.min(qty, s.stock.inTransit || 0);
  s.stock.inTransit = Math.max(0, (s.stock.inTransit || 0) - deductQty);

  if (whId === "WH-USA-02" || whObj.name.includes("FBA")) {
    s.stock.fba = (s.stock.fba || 0) + qty;
  } else {
    s.stock.usaAvailable = (s.stock.usaAvailable || 0) + qty;
  }

  // Record immutable transaction entry into SKU History Ledger
  const nowStr = new Date().toISOString().replace('T', ' ').slice(0, 19);
  AppState.skuHistory.unshift({
    timestamp: nowStr,
    sku: s.sku,
    type: "USA 3PL Physical GRN Receipt",
    qty: qty,
    source: `Ocean In-Transit (${blRef})`,
    dest: `${whObj.name} [${binLocation}]`,
    user: "Admin / Edison Receiving Dock",
    ref: `GRN: ${cbpRef}`
  });

  closeModal("crudModal");
  showToast(`Successfully received ${qty} rolls of ${s.sku} at ${whObj.name}! Physical stock unlocked for fulfillment.`, "success");
  renderCurrentView();
}


